import{a as e}from"./jsx-runtime-Bzw2jH9X.js";var t=e({default:()=>n}),n=JSON.parse(`[{"id":"qx-d2-001","clusterId":"D","werkstueckRef":"D.3.3","stufe":1,"question":"Wie ist das Verhalten des Teamleiters einzuordnen, und woran erkennst du es?","options":["Er stellt systematisch ihre Erinnerung und Wahrnehmung infrage, bis sie an sich selbst zweifelt. Das ist ein Angriff auf ihre Fähigkeit zu wissen, was wahr ist.","Er wertet sie im Meeting wiederholt ab, bis sie sich ständig bei ihm entschuldigt. Das ist ein Angriff auf ihr Ansehen und ihren Platz in der Gruppe.","Er beharrt im Streit um eine Zusage wiederholt auf seiner Sicht, sie auf ihrer. Das ist Aussage gegen Aussage, ein festgefahrener Konflikt ohne klaren Angreifer.","Er bestreitet wiederholt eigene Zusagen und bleibt dabei hart. Das ist ein Problem seiner Verlässlichkeit in der Sache; ihre Selbstzweifel sind eine Nebenfolge."],"correctIndex":0,"explanation":"Entscheidend ist das Muster, nicht die einzelne Lüge: Er leugnet Geschehenes, bestreitet ihre Erinnerung („Du erinnerst dich falsch“) und wertet ihre Einschätzung ab („überempfindlich“), und das wiederholt über Wochen. Die Folgen passen dazu: Sie zweifelt an sich selbst, fragt andere, ob sie sich alles einbildet, und entschuldigt sich ständig. Das nennt man Gaslighting, nach dem Theaterstück „Gas Light“ (1938), in dem ein Ehemann seiner Frau einredet, sie bilde sich das schwächer werdende Gaslicht nur ein. Gaslighting zielt darauf, dass jemand der eigenen Wahrnehmung nicht mehr traut. Schriftliche Notizen helfen dagegen, weil sie sich nicht wegleugnen lassen. Systematisches Abwerten kann Menschen verunsichern, hier geht es aber um das Leugnen von Geschehenem und das Bestreiten ihrer Erinnerung, nicht um den Verlust von Ansehen. Ein ehrlicher Erinnerungsstreit wäre es nicht: Ihre schriftliche Notiz liegt vor, und die Abwertung als „überempfindlich“ gehört nicht zu einem ehrlichen Streit.","coreRule":"⚡ Gaslighting ist nicht eine Lüge, sondern ein System: Es zielt darauf, dass du deiner eigenen Wahrnehmung nicht mehr traust.","beleg":"Werkstück D.3.3 (Kernidee, Kontext & Tiefe); Fn. gl-d-gaslight (Hamilton, „Gas Light“, Uraufführung 5. Dezember 1938, Richmond Theatre; MGM-Verfilmung 1944)","status":"entwurf","scenario":"Ein Teamleiter sagt im Meeting: „Das habe ich nie gesagt.“ Eine Mitarbeiterin hat die Zusage am Vortag schriftlich notiert und widerspricht. Er antwortet: „Du erinnerst dich falsch. Du bist in letzter Zeit ohnehin überempfindlich.“ Das passiert seit Wochen immer wieder. Inzwischen fragt sie Kollegen, ob sie sich wohl alles nur einbildet, und entschuldigt sich ständig bei ihm.","quote":"","quoteLabel":"","kurz":"Entscheidend ist das Muster über Wochen: Er leugnet Geschehenes, bestreitet ihre Erinnerung und wertet sie als „überempfindlich“ ab, bis sie selbst zweifelt. Das ist kein bloßer Streit um eine einzelne Zusage, sondern zielt auf ihr Vertrauen in die eigene Wahrnehmung.","prueffrage":"Was hat die Mitarbeiterin schriftlich, was entgegnet er darauf, und wie oft geht das schon so?","rueckmeldung":[{"option":1,"text":"Dass sie sich ständig entschuldigt, ist tatsächlich auffällig, und Abwertung kann verunsichern. Im Kern geht es hier aber nicht um ihr Ansehen, sondern darum, dass er Geschehenes leugnet und ihre Erinnerung bestreitet, bis sie ihrer eigenen Wahrnehmung nicht mehr traut."},{"option":2,"text":"Ein Konflikt, in dem beide auf ihrer Sicht beharren, klingt fair und neutral. Hier liegt aber ihre schriftliche Notiz vor, und die Abwertung als „überempfindlich“ gehört nicht zu einem ehrlichen Streit, schon gar nicht über Wochen und mit Folgen nur für sie."},{"option":3,"text":"Dass er Zusagen bestreitet, stimmt und ist ein Verlässlichkeitsproblem. Das greift aber zu kurz: Er bestreitet auch ihre Erinnerung und wertet ihre Einschätzung ab, und ihr Zweifel an sich selbst ist kein Nebeneffekt, sondern die Wirkung, auf die das Muster hinausläuft."}],"familie":"wahrnehmung-festhalten","fertigkeit":"F2","quellen":[{"typ":"doi","kurz":"Popat, N.; Pandey, J. (2026): Workplace gaslighting: a construct for organizational research. Frontiers in Psychology 17, 1589063","oeffentlich":true,"doi":"10.3389/fpsyg.2026.1589063","abruf":"2026-10-12"},{"typ":"url","kurz":"Johnsen, R. E. (2017): On the Origins of „Gaslighting“. Los Angeles Review of Books, 09.03.2017","oeffentlich":true,"url":"https://lareviewofbooks.org/article/on-the-origins-of-gaslighting/","abruf":"2026-10-12"}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v8","modell":"claude-sonnet-5-5","datum":"2026-10-15","urteil":"korrigieren","pruefsumme":"ced5eacdc5561161"}},{"id":"qx-d2-002","clusterId":"D","werkstueckRef":"D.3.3","stufe":2,"question":"Welcher Schritt hilft dir am besten, wieder festen Boden unter den Füßen zu bekommen?","scenario":"Eine Kollegin sagt dir immer wieder: „So war das nie“, „Du erinnerst dich falsch“, „Du bist gerade so empfindlich“. Du merkst, dass du dir selbst nicht mehr sicher bist, ob deine Erinnerung an die Gespräche stimmt.","options":["Du lässt die Kollegin ihre Version erklären, damit ihr euch gemeinsam auf eine Fassung der Gespräche einigt.","Du hältst Gespräche und Ereignisse zeitnah schriftlich fest, damit du später auf etwas Überprüfbares zurückgreifst.","Du fragst mehrere Bekannte, welche Version glaubwürdiger klingt, und richtest dich nach dem Urteil der Mehrheit.","Du gehst die Gespräche abends in Gedanken noch einmal durch, damit deine Erinnerung klar bleibt und du sicherer wirst."],"correctIndex":1,"explanation":"Wenn jemand systematisch bestreitet, was du erlebt hast, steht Aussage gegen Aussage, und deine eigene Wahrnehmung wirkt zunehmend unsicher. Ein geschriebenes Protokoll ist eine Waffe gegen das Leugnen der Vergangenheit: Mit Notizen zu Gesprächen und Ereignissen kannst du nachlesen, was war, statt nur im Kopf zu grübeln. Hilfreich ist die Frage: Was habe ich selbst gesehen und gehört?","coreRule":"⚡ Schreib auf, was geschieht: Ein Protokoll lässt sich nicht wegleugnen.","quote":"","quoteLabel":"","beleg":"Werkstück D.3.3 (Anti-Denkmuster, Aktivierungs-Frage und Logbuch)","status":"entwurf","kurz":"Wo Aussage gegen Aussage steht, hilft nur etwas Festes: Zeitnahe Notizen lassen dich nachlesen, was war, statt nur im Kopf zu grübeln. Der naheliegende Fehler ist, die Klärung bei anderen oder im Gedächtnis zu suchen, obwohl dort nichts Überprüfbares entsteht.","prueffrage":"Worauf stützt sich bisher deine Erinnerung an die Gespräche, und worauf die Version der Kollegin?","rueckmeldung":[{"option":0,"text":"Sich auszutauschen wirkt reif und versöhnlich. Doch gerade sie bestreitet die Gespräche, daher entstünde aus einer „gemeinsamen Fassung“ keine überprüfbare Grundlage, sondern vermutlich nur ein Kompromiss über etwas, das unklar bleibt."},{"option":2,"text":"Eine Außenperspektive kann entlasten. Die Bekannten waren aber nicht dabei und können nichts überprüfen; entscheiden würden dann Sympathie oder Mehrheit statt eines Belegs dafür, was tatsächlich gesagt wurde."},{"option":3,"text":"Gedankliches Durchgehen fühlt sich nach Klarheit an. Es ruft die Erinnerung aber nur erneut ab und schafft nichts Festes, auf das du dich später stützen könntest; leicht wird daraus bloßes Grübeln."}],"familie":"wahrnehmung-festhalten","fertigkeit":"F2","quellen":[{"typ":"doi","kurz":"Popat, N.; Pandey, J. (2026): Workplace gaslighting: a construct for organizational research. Frontiers in Psychology 17, 1589063","oeffentlich":true,"doi":"10.3389/fpsyg.2026.1589063","abruf":"2026-10-12"}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v5","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"125907e453467225"}},{"id":"qx-d2-003","clusterId":"D","werkstueckRef":"D.3.3","stufe":3,"question":"Eine Kollegin sagt dir mehrfach hintereinander: „Das habe ich nie gesagt“, obwohl du eine Mail von ihr hast, in der es steht. Als du darauf hinweist, meint sie: „Du bist in letzter Zeit so überempfindlich.“ Eine Bekannte rät dir: „Sei nicht so streng mit ihr. Ein bisschen Leugnen und Umdeuten ist in jedem Konflikt normal und hat auch seine nützliche Seite.“ Was ist an diesem Rat falsch?","options":["Er übersieht, dass die Kollegin hier schlicht gelogen hat, und eine Lüge über eine belegte Mail sollte man klar benennen, statt sie bloß als normales Konfliktverhalten abzutun.","Er übersieht, dass Leugnen belegter Tatsachen und Umdeuten der Wahrnehmung als Muster das Vertrauen in die eigene Erinnerung untergraben und keine nützliche Seite haben.","Er übersieht, dass Leugnen und Umdeuten nur dann schaden, wenn sie mit Absicht geschehen; ob die Kollegin bewusst so handelt, müsste man also erst klären.","Er übersieht, dass zwar das Leugnen der Mail schadet, ihr Satz, du seist „überempfindlich“, aber nur eine Meinung ist, die du ruhig gelassen nehmen kannst."],"correctIndex":1,"explanation":"Wer Dinge leugnet, die belegt sind (hier die Mail), und die Wahrnehmung des Gegenübers als „überempfindlich“ abtut, greift dessen Vertrauen in die eigene Erinnerung an; geschieht das wiederholt, spricht man von Gaslighting, nach dem Theaterstück „Gas Light“ von 1938. Dieses Muster hat keine harmlose oder nützliche Seite, denn es läuft darauf hinaus, dass das Gegenüber an der eigenen Wahrnehmung zweifelt, ob es nun bewusst oder unbewusst eingesetzt wird. Der Rat, das als normalen Konflikt hinzunehmen, ist deshalb ein Fehlschluss. Sinnvoller ist es, die eigene Wahrnehmung zu sichern, etwa mit Notizen und Belegen wie der Mail.","coreRule":"⚡ Gaslighting hat keine harmlose Dosis: Wer belegte Tatsachen leugnet und deine Wahrnehmung für unzuverlässig erklärt, schadet von Anfang an, egal ob mit Absicht oder ohne.","beleg":"Werkstück D.3.3 (Das Adaptive Talent; Der Kipppunkt)","status":"entwurf","scenario":"","kurz":"Wer Belegtes leugnet und das Gegenüber dann „überempfindlich“ nennt, lässt es an der eigenen Erinnerung zweifeln, und das gilt unabhängig von der Absicht. „Normaler Konflikt“ verharmlost genau dieses Muster, das keine nützliche Seite hat.","prueffrage":"Was steht in der Mail, was sagt die Kollegin dazu, und wie sicher wärst du dir nach dem dritten Mal noch?","rueckmeldung":[{"option":0,"text":"Dass die Mail der Kollegin widerspricht, spricht dafür, dass sie unrichtig behauptet. Ob sie dabei bewusst lügt, geht aus der Lage aber nicht hervor, und es kommt auch nicht darauf an: Der Rat verharmlost das Muster, nicht nur die einzelne Aussage."},{"option":2,"text":"Absicht ist oft eine nützliche Frage, wenn man ein Verhalten bewertet. Hier hängt der Schaden aber nicht davon ab: Das Muster lässt dich an deiner Erinnerung zweifeln, egal ob die Kollegin es bewusst oder unbewusst einsetzt."},{"option":3,"text":"Eine Gelassenheit gegenüber bloßen Meinungen ist meist sinnvoll. Das „überempfindlich“ ist hier aber keine freie Meinung: Es folgt auf deinen Hinweis auf die Mail und tut deine Wahrnehmung ab, gehört also zum selben Muster wie das Leugnen."}],"familie":"wahrnehmung-festhalten","fertigkeit":"F2","quellen":[{"typ":"doi","kurz":"Popat, N.; Pandey, J. (2026): Workplace gaslighting: a construct for organizational research. Frontiers in Psychology 17, 1589063","oeffentlich":true,"doi":"10.3389/fpsyg.2026.1589063","abruf":"2026-10-12"},{"typ":"url","kurz":"Johnsen, R. E. (2017): On the Origins of „Gaslighting“. Los Angeles Review of Books, 09.03.2017","oeffentlich":true,"url":"https://lareviewofbooks.org/article/on-the-origins-of-gaslighting/","abruf":"2026-10-12"}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v8","modell":"claude-sonnet-5-5","datum":"2026-10-15","urteil":"korrigieren","pruefsumme":"3895bd0717cfaf14"}},{"id":"qx-d2-004","clusterId":"D","werkstueckRef":"D.3.3","stufe":4,"question":"Warum ist dieses Vorgehen mehr als bloßes Überzeugen und eine Form von Gaslighting?","scenario":"Eine neue Bekannte nimmt dich zu einem Treffen ihrer Gruppe mit. Dort sagt ein Sprecher zu einem Neuling: „Dein früheres Denken war falsch und gehirngewaschen. Nur wir sagen dir, was wirklich wahr ist.“ Alles von außen, ob von Familie, Wissenschaftlern oder „Systemmedien“, gilt in der Gruppe als Lüge. Ein Mitglied erzählt dir später: „Früher habe ich selbst viel gezweifelt, aber heute weiß ich, dass ich mir nur noch von der Gruppe sagen lassen darf, was stimmt.“","options":["Die Gruppe erklärt sich zur einzigen Quelle der Wahrheit und bringt Mitglieder dazu, ihrem eigenen früheren Urteil zu misstrauen.","Die Gruppe stempelt Familie, Wissenschaft und Medien als Lüge ab, sodass Mitgliedern die Informationen für ein anderes Bild fehlen.","Die Gruppe verlangt Gehorsam gegenüber ihrem Sprecher, sodass Mitglieder seine Vorgaben befolgen, ohne sie noch zu hinterfragen.","Die Gruppe benutzt Kampfwörter wie „gehirngewaschen“ und „Systemmedien“, die Kritik abwehren und Gespräche in feste Bahnen lenken."],"correctIndex":0,"explanation":"Entscheidend ist, was mit dem Urteilsvermögen der Person passiert. Gaslighting zielt darauf ab, dass jemand der eigenen Wahrnehmung, Erinnerung und Urteilskraft nicht mehr traut und nur noch glaubt, was der Manipulator sagt. Hier geschieht genau das: Das frühere Denken wird pauschal als „gehirngewaschen“ entwertet, alles Äußere als Täuschung gebrandmarkt, und die Gruppe setzt sich als einzige Wahrheitsquelle. Das isoliert von Familie, Wissenschaft und Medien und macht abhängig von der Einschätzung der Gruppe. Gute Überzeugungsarbeit würde dagegen Gründe nennen, die man selbst prüfen kann, und das eigene Urteil der Person stärken statt ersetzen.","coreRule":"⚡ Wer dir sagt, nur er kenne die Wahrheit und dein früheres Denken sei wertlos, will nicht überzeugen, sondern dein Urteil ersetzen.","beleg":"Werkstück D.3.3 (Anwendung & Relevanz, „In Kulten und Verschwörungsmythen“; Verbindungen)","status":"entwurf","kurz":"Entscheidend ist, was mit dem Urteilsvermögen geschieht: Die Gruppe entwertet das frühere Denken als „gehirngewaschen“ und setzt sich als einzige Wahrheitsquelle. Gute Überzeugung nennt Gründe, die man selbst prüfen kann.","prueffrage":"Bekommst du Gründe genannt, die du selbst nachprüfen kannst, oder nur die Auskunft, wem du glauben darfst?","rueckmeldung":[{"option":1,"text":"Dass alles Äußere als Lüge gilt, isoliert tatsächlich und verknappt die Informationen. Das allein erklärt aber noch kein Gaslighting: Der Kern liegt darin, dass die Person dem eigenen Urteil nicht mehr traut."},{"option":2,"text":"Die Abhängigkeit vom Sprecher ist im Szenario spürbar. Gehorsam allein ist aber noch kein Gaslighting, denn es geht darum, dass die Person ihrer eigenen Wahrnehmung und Urteilskraft nicht mehr traut."},{"option":3,"text":"Solche Etiketten wehren Kritik ab und lenken Gespräche, das stimmt. Sie sind aber nur ein Mittel. Gaslighting zeigt sich erst darin, wie sich das Vertrauen der Person in ihr eigenes Urteil verändert."}],"familie":"wahrnehmung-festhalten","fertigkeit":"F2","quellen":[{"typ":"doi","kurz":"Popat, N.; Pandey, J. (2026): Workplace gaslighting: a construct for organizational research. Frontiers in Psychology 17, 1589063","oeffentlich":true,"doi":"10.3389/fpsyg.2026.1589063","abruf":"2026-10-12"}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v8","modell":"claude-sonnet-5-5","datum":"2026-10-15","urteil":"ok","pruefsumme":"3c21c2514a0325d8"}},{"id":"qx-d2-005","clusterId":"D","werkstueckRef":"D.3.4","stufe":1,"question":"Was ist an dieser Reaktion des Vaters als Gesprächsbeitrag das Hauptproblem?","scenario":"Beim Abendessen erzählst du, was du im Seminar über strukturelle Ursachen von Armut gelernt hast: Bildungschancen, soziale Herkunft, Benachteiligung. Dein Vater winkt ab und sagt in einem Ton, der keine Widerrede zulässt: „Am Ende ist es doch ganz einfach: Jeder ist seines Glückes Schmied.“","options":["Er beantwortet eine vielschichtige Frage mit einer endgültig klingenden Allerweltsweisheit und beendet so das Gespräch, ohne auf deine Argumente einzugehen.","Er stellt deinen Argumenten aus dem Seminar ein Sprichwort gegenüber und behauptet so das Gegenteil, ohne selbst Zahlen oder Beispiele zu nennen, die es stützen könnten.","Er spricht in einem Ton, der keine Widerrede zulässt, und verletzt so den Respekt, obwohl sein Einwand freundlich vorgetragen ein durchaus fairer Beitrag wäre.","Er führt Armut allein auf eigene Anstrengung zurück und erklärt so Bildungschancen und soziale Herkunft für unwichtig, die du gerade als Ursachen genannt hast."],"correctIndex":0,"explanation":"Der Satz klingt weise und endgültig, geht aber auf keines deiner Argumente ein. Er ersetzt die Auseinandersetzung durch eine Formel und signalisiert: Das Thema ist für mich erledigt, und du brauchst auch nicht weiter nachzudenken. Ob das Sprichwort im Kern etwas Wahres trifft, ist dafür unerheblich. Entscheidend ist seine Funktion im Gespräch: Es soll die Diskussion beenden, nicht klären. Eine gute Antwort darauf ist, das Klischee „auszupacken“ und zu fragen, wie die Phrase bei den konkreten Details dieses Problems weiterhilft.","coreRule":"⚡ Ein Satz, der eine Frage beendet, statt sie zu beantworten, ist ein Rollladen und kein Argument.","quote":"Sie hat die komplexe, nuancierte Debatte nicht widerlegt, sondern sie einfach kurzgeschlossen.","quoteLabel":"Merksatz:","beleg":"Werkstück D.3.4 (Das Gespräch am Familientisch; Kernidee)","status":"entwurf","kurz":"Der Satz klingt endgültig und weise, ersetzt aber die Auseinandersetzung durch eine Formel: Auf kein Argument wird eingegangen, das Thema gilt als erledigt. Ob das Sprichwort etwas Wahres trifft, ist dafür unerheblich.","prueffrage":"Wie könnte das Gespräch nach diesem Satz sinnvoll weitergehen, und was hat der Vater dafür angeboten?","rueckmeldung":[{"option":1,"text":"Dass keine Belege kommen, stimmt. Aber auch mit Zahlen oder Beispielen könnte man so abwinken. Entscheidend ist, dass der Satz das Gespräch beendet, statt auf deine Argumente einzugehen."},{"option":2,"text":"Der Ton macht das Gespräch gewiss schwerer. Doch auch freundlich vorgetragen bliebe der Satz eine Phrase, die auf nichts eingeht. Das Problem liegt weniger im Ton als in dem, was der Satz im Gespräch bewirkt."},{"option":3,"text":"Der Vater sagt nicht, Bildung und Herkunft spielten keine Rolle, das legst du ihm in den Mund. Sein Satz greift das Thema gar nicht auf, sondern beendet es. Der Fehler liegt in der Gesprächsfunktion, nicht in einer zugespitzten These."}],"familie":"floskel-entpacken","fertigkeit":"F2","quellen":[{"typ":"literatur","kurz":"Lifton, R. J. (1961): Thought Reform and the Psychology of Totalism: A Study of „Brainwashing“ in China. Kap. 22 „Ideological Totalism“, Abschnitt „Loading the Language“ (Nachdruck Chapel Hill: University of North Carolina Press 1989)","oeffentlich":false}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v7","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"9d183d951834d85d"}},{"id":"qx-d2-006","clusterId":"D","werkstueckRef":"D.3.4","stufe":2,"question":"Welche Reaktion bringt das Gespräch am besten wieder auf die Sache?","scenario":"Du kritisierst eine angebliche Heilmethode und fragst, welche Belege es für ihre Wirkung gibt. Dein Gegenüber antwortet nur: „Vertraue einfach dem Prozess.“","options":["Die Frage nach Belegen noch einmal deutlich wiederholen und so lange darauf bestehen, bis eine Studie genannt wird.","Nachfragen, was diese Phrase im vorliegenden Fall konkret leistet und woran man erkennen würde, dass die Methode wirkt.","Die Antwort offen als Totschlagphrase benennen und erklären, dass ohne Belege nicht weiter darüber gesprochen wird.","Der Person zustimmen, dass Vertrauen wichtig ist, und sie fragen, welche Erfahrungen sie selbst mit der Methode gemacht hat."],"correctIndex":1,"explanation":"„Vertraue einfach dem Prozess“ beantwortet deine Frage nach Belegen nicht, sondern beendet sie. Hilfreich ist, die Phrase auf den konkreten Fall anzuwenden: Was genau soll hier geschehen, und woran würde man merken, dass die Methode wirkt oder nicht wirkt? So wird aus der Floskel wieder eine prüfbare Behauptung. Und die Frage nach persönlichen Erfahrungen klingt zugewandt, liefert aber nur Einzelberichte statt Belege.","coreRule":"⚡ Packe die Floskel aus: Frag, was sie im konkreten Fall tatsächlich leistet.","beleg":"Werkstück D.3.4 (Anwendung & Relevanz, Esoterik & New Age: „Vertraue einfach dem Prozess“; Das Anti-Denkmuster, Aktivierungs-Frage)","status":"entwurf","kurz":"„Vertraue einfach dem Prozess“ beendet deine Belegfrage, statt sie zu beantworten. Nachfragen, was genau geschehen soll und woran man eine Wirkung erkennt, macht aus der Floskel wieder eine prüfbare Behauptung.","prueffrage":"Was weißt du nach dieser Antwort mehr über die Wirkung der Methode als vorher?","rueckmeldung":[{"option":0,"text":"Deine Belegfrage ist berechtigt, und sie fallen zu lassen wäre falsch. Wörtlich wiederholt gibt sie der Person aber nichts, woran sie anknüpfen kann, und die Phrase bleibt unangetastet. Konkreter wird es erst, wenn du sie auf den Fall beziehst."},{"option":2,"text":"Dass die Phrase deine Frage nicht beantwortet, stimmt. Ein Etikett samt Gesprächsabbruch beendet das Gespräch aber nun auch von deiner Seite und macht aus der Floskel keine prüfbare Behauptung, über die man weitersprechen könnte."},{"option":3,"text":"Zugewandt zu bleiben kann das Gespräch offen halten. Erfahrungsberichte beantworten aber deine ursprüngliche Frage nicht: Sie sind Einzelfälle, keine Belege für eine Wirkung, und die Belegfrage gerät dabei aus dem Blick."}],"familie":"floskel-entpacken","fertigkeit":"F2","quellen":[{"typ":"literatur","kurz":"Lifton, R. J. (1961): Thought Reform and the Psychology of Totalism. Kap. 22, Abschnitt „Loading the Language“ (Nachdruck UNC Press 1989)","oeffentlich":false}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v8","modell":"claude-sonnet-5-5","datum":"2026-10-15","urteil":"ok","pruefsumme":"213f521746e03ab3"}},{"id":"qx-d2-007","clusterId":"D","werkstueckRef":"D.3.4","stufe":3,"question":"Beim Familienessen spricht eine Studentin über strukturelle Ursachen von Armut. Ihr Vater winkt ab: „Am Ende ist es doch ganz einfach: Jeder ist seines Glückes Schmied.“ Worin liegt das eigentliche Problem seiner Reaktion?","options":["Er benutzt das Sprichwort als abschließende Antwort, ohne auf ihre Argumente einzugehen, und beendet damit das Gespräch, statt es zu prüfen.","Er führt Armut auf eine einzige Ursache zurück, die eigene Anstrengung, und blendet damit die strukturellen Ursachen aus, die sie genannt hat.","Er antwortet mit einem Sprichwort, und Sprichwörter haben in einer Sachdiskussion nichts zu suchen, weil sie keine Argumente sind.","Er wechselt das Thema von gesellschaftlichen Strukturen zur Verantwortung des Einzelnen und redet so an ihren Argumenten vorbei."],"correctIndex":0,"explanation":"Ein Sprichwort zur Illustration ist völlig normal, denn solche Redewendungen sind nützliche Abkürzungen und „kultureller Klebstoff“. Zum Problem wird es, wenn es die Funktion eines Schlussstrichs bekommt: Die Studentin hat strukturelle Ursachen genannt, und der Vater geht auf keine davon ein, sondern erklärt die Debatte mit einer Phrase für beendet. Dabei muss die Phrase weder logisch noch wahr sein, um so zu wirken, denn ihre Kraft liegt in der scheinbaren Endgültigkeit und sozialen Akzeptanz. Entscheidend ist also nicht der Inhalt des Spruchs, sondern was er im Gespräch tut: Er ersetzt die Prüfung der Argumente. Wer ihn auspacken will, fragt, wie genau er auf dieses konkrete Problem passt und was er an den genannten Ursachen ändert.","coreRule":"⚡ Nicht das Sprichwort ist das Problem, sondern seine Verwendung als Fragenkiller: Er ersetzt die Prüfung durch eine Phrase.","beleg":"Werkstück D.3.4 (Das Adaptive Talent; Kontext & Tiefe; Der Kipppunkt)","status":"entwurf","scenario":"","quote":"","quoteLabel":"","kurz":"Der Spruch ist nicht das Problem, sondern was er im Gespräch tut: Er erklärt die Debatte für beendet, ohne dass der Vater auf eine der genannten Ursachen eingeht. Er ersetzt damit die Prüfung der Argumente, obwohl Sprichwörter als Abkürzung durchaus nützlich sein können.","prueffrage":"Wäre die Reaktion des Vaters weniger problematisch, wenn er denselben Gedanken in eigenen Worten statt als Sprichwort gesagt hätte?","rueckmeldung":[{"option":1,"text":"Der Spruch betont tatsächlich die eigene Anstrengung und übergeht die genannten Ursachen. Dass der Vater nur eine Ursache gelten lässt, steht aber nirgends. Entscheidend ist, dass er mit der Phrase das Gespräch beendet, statt ihre Argumente zu prüfen."},{"option":2,"text":"Ein Sprichwort allein ist zwar noch kein Argument. Als Illustration oder Abkürzung ist es in einer Sachdiskussion aber völlig in Ordnung. Zum Problem wird es erst, wenn es wie ein Schlussstrich eingesetzt wird und die Prüfung der Argumente ersetzt."},{"option":3,"text":"Dass der Vater auf keines ihrer Argumente eingeht, stimmt. Er wechselt aber nicht das Thema, denn sein Spruch bezieht sich weiter auf Armut. Der Kern liegt darin, dass er die Debatte mit einer Phrase für erledigt erklärt, statt sie zu prüfen."}],"familie":"floskel-entpacken","fertigkeit":"F2","quellen":[{"typ":"literatur","kurz":"Lifton, R. J. (1961): Thought Reform and the Psychology of Totalism. Kap. 22, Abschnitt „Loading the Language“ (Nachdruck UNC Press 1989)","oeffentlich":false}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v8","modell":"claude-sonnet-5-5","datum":"2026-10-15","urteil":"korrigieren","pruefsumme":"7c6deb15c8bb9cb5"}},{"id":"qx-d2-008","clusterId":"D","werkstueckRef":"D.3.4","stufe":4,"question":"Wie reagierst du am besten auf diesen Gesprächsausgang?","options":["Du merkst, dass der Satz nichts widerlegt hat, und fragst, was er im konkreten Fall erklärt: etwa, wie ein Kind ohne weiterführende Schule vor Ort „schmieden“ soll.","Du merkst, dass der Satz einen wahren Kern hat, und schlägst vor, sich in der Mitte zu treffen: Eigenverantwortung zählt, die im Seminar genannten Ursachen aber auch.","Du merkst, dass der Vater selbst nichts belegt hat, und hältst ihm entgegen, was die Forschung zu Bildungschancen und Herkunft zeigt, damit er seinen Satz überdenkt.","Du merkst, dass der Vater abgewunken hat, und lässt das Thema für heute ruhen, um es später in ruhigerem Rahmen noch einmal behutsam aufzugreifen."],"correctIndex":0,"explanation":"Der Satz wirkt endgültig, widerlegt aber nichts: Er ersetzt die Auseinandersetzung mit den genannten Faktoren durch eine allgemeine Formel. Solche Phrasen beenden das Nachdenken, statt es voranzubringen. Sinnvoll ist deshalb, die Formel auf den konkreten Fall anzuwenden und zu prüfen, was sie dort tatsächlich erklärt. So wird die Diskussion wieder auf die Sachebene gezwungen. Ein ebenso allgemeines Gegenwort ersetzt die Phrase nur durch eine zweite, ohne etwas zu prüfen. Das Sprichwort pauschal für unzulässig zu erklären, ersetzt die Phrase nur durch einen anderen Gesprächsabbruch. Von der Tochter zuerst Quellen zu verlangen, verschiebt die Beweislast, obwohl der Vater selbst nichts belegt hat.","coreRule":"⚡ Eine Phrase, die eine komplexe Frage beendet statt beantwortet, prüfst du, indem du sie auf den konkreten Fall anwendest.","beleg":"Werkstück D.3.4 (Kontext & Tiefe); Fn. gl-d-lifton (Lifton 1961/1989, Kap. 22, „Loading the Language“, S. 429)","status":"entwurf","scenario":"Beim Abendessen erzählt eine Studentin ihren Eltern, was sie im Seminar über die Ursachen von Armut gelernt hat: Bildungschancen, familiäre Herkunft, regionale Unterschiede. Ihr Vater winkt ab: „Am Ende ist es doch ganz einfach: Jeder ist seines Glückes Schmied.“ Das Gespräch verstummt.","quote":"","quoteLabel":"","kurz":"Der Satz wirkt wie ein Schlusswort, erklärt aber nichts. Wer ihn auf den konkreten Fall anwendet, zwingt das Gespräch zurück auf die Sachebene, statt der Formel nur eine zweite Formel entgegenzusetzen.","prueffrage":"Woran könntest du erkennen, ob das Schweigen am Tisch Zustimmung bedeutet oder nur ein abgebrochenes Gespräch?","rueckmeldung":[{"option":1,"text":"Eigenverantwortung zählt tatsächlich, und das Entgegenkommen wirkt versöhnlich. Aber der Vater hat gar keine begründete Position vorgebracht, deren Mitte man suchen könnte. So steht neben der einen Formel nur eine zweite, und geprüft wird nichts."},{"option":2,"text":"Der Verweis auf die Forschung zu Bildungschancen und Herkunft liegt nahe, weil der Vater tatsächlich nichts belegt hat. Doch dem Vater bleibt dann nur, den Satz zu verteidigen, während die Frage, was er im konkreten Fall erklärt, ungeprüft bleibt."},{"option":3,"text":"Das Thema ruhen zu lassen kann taktvoll sein, besonders wenn die Stimmung angespannt ist. Der Satz bleibt dann aber als scheinbares Schlusswort stehen, und die Phrase hat das Nachdenken beendet, ohne dass etwas geprüft wurde."}],"familie":"floskel-entpacken","fertigkeit":"F2","quellen":[{"typ":"literatur","kurz":"Lifton, R. J. (1961): Thought Reform and the Psychology of Totalism. Kap. 22, Abschnitt „Loading the Language“ (Nachdruck UNC Press 1989)","oeffentlich":false}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v8","modell":"claude-sonnet-5-5","datum":"2026-10-15","urteil":"korrigieren","pruefsumme":"b7cea481ebe88878"}},{"id":"qx-d2-009","clusterId":"D","werkstueckRef":"D.3.5","stufe":1,"question":"Wie beurteilst du deine Antwort?","scenario":"Du sagst: „Kein echter Fan unseres Vereins pöbelt im Stadion.“ Dein Freund zeigt dir einen Mann im Vereinstrikot, der Gästefans beschimpft hat. Du antwortest: „Dann ist das eben kein echter Fan.“ Dein Freund fragt: „Woran erkenne ich denn einen echten Fan?“ Du sagst: „Na, daran, dass er nicht pöbelt.“","options":["Deine Antwort macht die Aussage leer, denn du definierst „echter Fan“ nachträglich so, dass der pöbelnde Mann nicht mehr zählt und nichts Prüfbares bleibt.","Deine Antwort ist berechtigt, denn ein Vereinstrikot macht noch niemanden zum echten Fan, und wer Gästefans beschimpft, zeigt gerade kein Fanverhalten.","Deine Antwort ist eine zulässige Präzisierung, denn du legst nur nachträglich offen, was du mit „echter Fan“ von Anfang an gemeint hattest.","Deine Antwort ist unnötig, denn ein einzelner pöbelnder Mann widerlegt eine Aussage über die Fans eines ganzen Vereins ohnehin noch nicht."],"correctIndex":0,"explanation":"Ursprünglich war deine Aussage überprüfbar: Man hätte einen pöbelnden Fan finden können, um sie zu widerlegen. Mit dem eingeschobenen „echt“ ist sie es nicht mehr. Ein „echter Fan“ ist jetzt per Definition einer, der nicht pöbelt, und die Aussage lautet nur noch: „Wer nicht pöbelt, pöbelt nicht.“ Das stimmt immer und sagt nichts über die Welt. Statt die Behauptung am Gegenbeispiel zu prüfen und womöglich einzuschränken („Die meisten Fans pöbeln nicht“), hast du das Gegenbeispiel aus der Kategorie ausgeschlossen. Das ist die nachträgliche Immunisierung, die als „Kein wahrer Schotte“-Fehlschluss bekannt ist.","coreRule":"⚡ Wenn ein Gegenbeispiel auftaucht und du die Definition änderst, statt die Behauptung zu prüfen, hast du sie unwiderlegbar und damit inhaltsleer gemacht.","beleg":"Werkstück D.3.5 (Kernidee; Red Flags)","status":"entwurf","kurz":"Mit dem eingeschobenen „echt“ ist ein pöbelnder Fan per Definition ausgeschlossen, und die Aussage lautet nur noch: „Wer nicht pöbelt, pöbelt nicht.“ Das stimmt immer und sagt nichts mehr. Das Gegenbeispiel hätte eher zu einer Einschränkung führen sollen.","prueffrage":"Welche Beobachtung im Stadion würde deine Aussage noch widerlegen können?","rueckmeldung":[{"option":1,"text":"Ein Trikot allein macht niemanden zum Fan, das stimmt. Doch wenn Pöbeln schon per Definition ausschließt, ein „echter Fan“ zu sein, kann dich nichts mehr widerlegen. Du hast das Gegenbeispiel aus der Kategorie entfernt, statt die Behauptung daran zu prüfen."},{"option":2,"text":"Eine Präzisierung wäre in Ordnung, wenn sie die Aussage prüfbar hielte. Hier kommt das „echt“ aber erst, als das Gegenbeispiel auftaucht, und es ist so bestimmt, dass genau dieses Beispiel nicht mehr zählt. Dadurch ist die Aussage gegen jede Widerlegung geschützt."},{"option":3,"text":"Für eine Aussage ohne Ausnahme genügt ein einziges Gegenbeispiel, es ist also durchaus relevant. Das Problem liegt in deiner Reaktion: Statt die Aussage einzuschränken („Die meisten Fans pöbeln nicht“), hast du den Mann aus der Kategorie ausgeschlossen."}],"familie":"definition-nachtraeglich","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Dowden, B.: Fallacies (Abschnitt No True Scotsman). Internet Encyclopedia of Philosophy","oeffentlich":true,"url":"https://iep.utm.edu/fallacy/","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Flew, A. (1975): Thinking About Thinking. London: Fontana","oeffentlich":false}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v8","modell":"claude-sonnet-5-5","datum":"2026-10-15","urteil":"korrigieren","pruefsumme":"de32c49a0e8109a5"}},{"id":"qx-d2-010","clusterId":"D","werkstueckRef":"D.3.5","stufe":2,"question":"Marta behauptet: „Alle Menschen, die sich ernsthaft für Gesundheit interessieren, ernähren sich bewusst.“ Als Tom einen bekannten Gesundheitsberater nennt, der täglich Fast Food isst, antwortet sie: „Dann interessiert er sich eben nicht wirklich für Gesundheit.“ Warum ist Martas Behauptung nach dieser Antwort kaum noch etwas wert?","options":["Marta spricht dem Berater das echte Interesse ab, statt auf Toms Beispiel einzugehen; so ersetzt sie ein Argument durch ein Urteil über einen Menschen.","Ob jemand „wirklich“ interessiert ist, zeigt nur noch die bewusste Ernährung; im Kern heißt die Aussage: „Wer sich bewusst ernährt, ernährt sich bewusst.“","Toms Beispiel hat die Aussage bereits widerlegt; Martas Antwort ist nur ein Ausweichen, und im Kern bleibt eine Behauptung, die sich als falsch erwiesen hat.","Mit „wirklich“ zieht Marta ihre Aussage auf eine engere Gruppe zurück; über die meisten Gesundheitsinteressierten sagt sie damit nichts mehr aus."],"correctIndex":1,"explanation":"Vorher war die Behauptung prüfbar: Ein Gesundheitsinteressierter mit schlechter Ernährung hätte sie widerlegt. Genau so jemand wurde genannt. Marta rettet ihre Aussage, indem sie das Gegenbeispiel aus der Kategorie wirft. Das Kriterium für „wirklich interessiert“ ist nun genau das, was behauptet wird, und die Aussage lautet im Kern: „Wer sich bewusst ernährt, ernährt sich bewusst.“ Das ist immer wahr und sagt nichts mehr über die Welt.","coreRule":"⚡ Prüfe, ob sich das Kriterium für „wirklich“ unabhängig von der Behauptung bestimmen lässt; sonst ist die Behauptung leer.","beleg":"Werkstück D.3.5 (Kontext & Tiefe, „Der Mechanismus“)","status":"entwurf","scenario":"","kurz":"Marta macht „bewusste Ernährung“ nun zum Maßstab für „echtes Interesse“. Damit steht in ihrer Aussage im Kern nur noch, wer sich bewusst ernährt, ernähre sich bewusst. Das ist immer wahr, aber auch leer und lässt sich durch nichts mehr widerlegen.","prueffrage":"Welches Ergebnis hätte Martas Aussage vorher widerlegt, und gibt es dieses Ergebnis nach ihrer Antwort noch?","rueckmeldung":[{"option":0,"text":"Marta geht tatsächlich nicht auf das Beispiel ein und urteilt stattdessen über den Berater. Entscheidend ist aber, woran sie sein Interesse misst: am Verhalten, das gerade bewiesen werden sollte. Dadurch wird die Aussage unwiderlegbar."},{"option":2,"text":"Ein genanntes Gegenbeispiel kann eine Behauptung widerlegen, und Marta weicht ihm aus. Der Punkt ist hier aber ein anderer: Ihre Aussage war vorher prüfbar und wird nun so umgedeutet, dass sie gar nichts mehr sagt."},{"option":3,"text":"Mit „wirklich“ wird die Gruppe der Gesundheitsinteressierten tatsächlich enger. Nach welchem Maßstab, ist der Knackpunkt: Zur Gruppe gehört nur, wer sich bewusst ernährt. Die Aussage wird dadurch nicht schmaler, sondern leer."}],"familie":"definition-nachtraeglich","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Dowden, B.: Fallacies (Abschnitt No True Scotsman). Internet Encyclopedia of Philosophy","oeffentlich":true,"url":"https://iep.utm.edu/fallacy/","abruf":"2026-10-12"}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v8","modell":"claude-sonnet-5-5","datum":"2026-10-15","urteil":"korrigieren","pruefsumme":"926d11ee0d910f21"}},{"id":"qx-d2-011","clusterId":"D","werkstueckRef":"D.3.5","stufe":3,"question":"Wie beurteilst du Lenas Satz zur Nichte und ihre Antwort an den Bruder?","options":["Der Satz zur Nichte setzt einen Maßstab, den Jonas’ Lüge nicht widerlegen kann; die Antwort an den Bruder rettet ihre Aussage über ihre Freunde, indem sie „Freund“ erst nach der Lüge enger fasst.","Beide Sätze sind gleich fragwürdig, weil Lena jedes Mal das Wort „echt“ benutzt; schon dieses Wort zeigt, dass sie Gegenbeispiele wie Jonas von vornherein aus ihrem Freundeskreis ausschließen will.","Beide Sätze sind unbedenklich, weil Lena selbst festlegen darf, wen sie Freund nennt; Jonas nach seiner Lüge herauszunehmen, ist dieselbe erlaubte Festlegung wie ihr Maßstab gegenüber der Nichte.","Der Satz zur Nichte ist der Fehlschluss, weil er ein Ideal als Beschreibung echter Freunde ausgibt; die Antwort an den Bruder ist dagegen sauber, weil sie nur auf Jonas’ tatsächliche Lüge reagiert."],"correctIndex":0,"explanation":"Lenas Satz zur Nichte ist eine Norm: Er behauptet nichts über die Welt, sondern legt fest, was man von Freunden erwarten darf. Ein Gegenbeispiel wie Jonas kann ihn nicht widerlegen, und er muss es auch nicht. „Alle meine Freunde sind ehrlich zu mir“ dagegen ist eine Tatsachenbehauptung, und Jonas’ Lüge widerlegt sie. Statt die Behauptung zu prüfen, verengt Lena den Begriff „Freund“ nachträglich so, dass Jonas herausfällt; übrig bleibt „Alle ehrlichen Freunde sind ehrlich“, eine Aussage, die nichts mehr behauptet und nicht mehr falsch sein kann. Verräterisch ist der Wechsel von „Stimmt das?“ zu „Wer zählt überhaupt dazu?“. Dass das Wort „echt“ in beiden Sätzen vorkommt, macht noch keinen Fehlschluss, entscheidend ist, wozu es dient. Eine Festlegung vorab ist erlaubt, eine Festlegung erst nach dem Gegenbeispiel, um eine Tatsachenbehauptung zu retten, ist es nicht. Und der Satz zur Nichte beschreibt keine Tatsache, er setzt einen Maßstab; der Fehler liegt in der Antwort an den Bruder.","coreRule":"⚡ Normen setzen ist erlaubt, Tatsachen mit einer nachträglichen Definition retten nicht.","beleg":"Werkstück D.3.5 (Das Adaptive Talent; Der Kipppunkt; Red Flags)","status":"entwurf","scenario":"Lena sagt ihrer zwölfjährigen Nichte, die von einer Freundin enttäuscht wurde: „Ein echter Freund würde dich nicht belügen.“ Eine Woche später erzählt Lena ihrem Bruder: „Alle meine Freunde sind ehrlich zu mir.“ Der Bruder erinnert sie daran, dass Jonas sie neulich über das geliehene Fahrrad angelogen hat. Lena antwortet: „Dann war Jonas eben kein echter Freund.“","kurz":"Der Satz zur Nichte setzt einen Maßstab, den ein Gegenbeispiel nicht trifft. Die Aussage über ihre Freunde ist eine Tatsachenbehauptung: Wer „Freund“ erst nach Jonas’ Lüge enger fasst, prüft sie nicht mehr, sondern rettet sie.","prueffrage":"Was hätte sich an Lenas Aussage über ihre Freunde geändert, wenn sie vor dem Hinweis des Bruders gesagt hätte, wen sie zu ihnen zählt?","rueckmeldung":[{"option":1,"text":"Das Wort „echt“ steht tatsächlich in beiden Sätzen, ein Fehlschluss entsteht daraus aber nicht. Es kommt darauf an, wozu es dient: Beim Satz zur Nichte formuliert es einen Maßstab, erst in der Antwort an den Bruder schließt es ein Gegenbeispiel aus."},{"option":2,"text":"Lena darf vorab festlegen, was sie von Freunden erwartet; das stimmt. Jonas aber erst nach seiner Lüge aus dem Begriff zu nehmen, um die Behauptung über ihre Freunde zu retten, ist etwas anderes als ein Maßstab vorab."},{"option":3,"text":"Die Bewertung ist vertauscht. Der Satz zur Nichte behauptet nichts über die Welt, er sagt, was man von Freunden erwarten darf, und wird durch Gegenbeispiele nicht berührt. Die Antwort an den Bruder reagiert nicht nur auf die Lüge, sie verändert dafür den Begriff „Freund“."}],"familie":"definition-nachtraeglich","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Dowden, B.: Fallacies (Abschnitt No True Scotsman). Internet Encyclopedia of Philosophy","oeffentlich":true,"url":"https://iep.utm.edu/fallacy/","abruf":"2026-10-12"}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v4","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"ok","pruefsumme":"2b827be65b7a1522"}},{"id":"qx-d2-012","clusterId":"D","werkstueckRef":"D.3.5","stufe":4,"question":"Welche Rückfrage prüft die Behauptung des Coaches am besten?","scenario":"Ein Diätcoach sagt: „Wer sich wirklich an den Plan hält, nimmt ab. Wer nicht abnimmt, hat sich eben nicht wirklich daran gehalten.“","options":["Wer hat den Plan entwickelt, und verdient der Coach daran, wenn Menschen ihn kaufen?","Ist Abnehmen überhaupt das richtige Ziel, oder kommt es für die Gesundheit auf anderes an?","Welche Ausbildung hat der Coach, und wie lange arbeitet er schon in diesem Bereich?","Woran erkennt man vorab, wer sich richtig an den Plan gehalten hat, unabhängig vom Abnehmen?"],"correctIndex":3,"explanation":"Der Coach verschärft die Bedingung nachträglich: „Sich wirklich an den Plan halten“ heißt in seinem Satz faktisch „hat abgenommen“. Dadurch wird die Behauptung zur Tautologie („Wer abnimmt, nimmt ab“) und kann nie mehr widerlegt werden, denn jedes Scheitern wird einfach dem Anwender zugeschrieben. Die beste Prüfung verlangt ein Kriterium für „wirklich gehalten“, das unabhängig vom Ergebnis feststellbar ist, etwa Ernährungstagebuch, Wiegen der Portionen oder Kontrolle durch Dritte. Gibt es ein solches Kriterium nicht, sagt die Behauptung nichts über den Plan aus. Ob der Coach am Verkauf verdient oder welche Ausbildung er hat, kann für das Vertrauen eine Rolle spielen, sagt aber nichts darüber, ob seine Behauptung überhaupt widerlegbar ist. Ob Abnehmen das richtige Ziel ist, ist eine andere Frage als die nach der Behauptung des Coaches.","coreRule":"⚡ Verlange ein Kriterium für „echt“ oder „wirklich“, das nicht schon das Ergebnis voraussetzt.","beleg":"Werkstück D.3.5 (Anwendung & Relevanz, „Pseudowissenschaft & Kulte“; Anti-Denkmuster, Skript 2)","status":"entwurf","kurz":"Der Coach macht „sich wirklich halten“ nachträglich zu „hat abgenommen“, damit kann ihm nichts widersprechen. Prüfbar wird die Aussage erst, wenn sich das Einhalten unabhängig vom Ergebnis feststellen lässt, etwa per Tagebuch.","prueffrage":"Welches Ergebnis eines Teilnehmers könnte der Coach überhaupt als Fehlschlag seines Plans anerkennen?","rueckmeldung":[{"option":0,"text":"Ein Verdienst am Verkauf kann Misstrauen wecken und ist durchaus bedenkenswert. Er verrät aber nicht, ob die Behauptung überhaupt widerlegbar ist; selbst ein Coach ohne Eigeninteresse könnte diesen Satz sagen."},{"option":1,"text":"Ob Abnehmen das richtige Ziel ist, ist eine eigene, berechtigte Frage. Sie betrifft aber die Wahl des Ziels, nicht die Aussage des Coaches, die sich gegen jedes Gegenbeispiel absichert."},{"option":2,"text":"Ausbildung und Erfahrung können das Vertrauen in einen Coach beeinflussen. Sie sagen aber nicht, ob seine Behauptung widerlegbar ist, denn auch ein erfahrener Coach kann jedes Scheitern den Anwendern zuschreiben."}],"familie":"definition-nachtraeglich","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Dowden, B.: Fallacies (Abschnitt No True Scotsman). Internet Encyclopedia of Philosophy","oeffentlich":true,"url":"https://iep.utm.edu/fallacy/","abruf":"2026-10-12"}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v4","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"ok","pruefsumme":"31a84875bde332af"}},{"id":"qx-d2-013","clusterId":"D","werkstueckRef":"D.3.6","stufe":1,"question":"Was ist an dieser Begründung das Problem?","scenario":"„Wie funktioniert die Wünschelrute?“ – „Sie reagiert auf Erdstrahlen.“ – „Was sind Erdstrahlen?“ – „Das, worauf die Wünschelrute reagiert.“","options":["Jede Seite stützt nur die andere; für keine der beiden gibt es einen Beleg, der von der anderen unabhängig ist.","Es fehlt nur ein Versuch: Schlägt die Rute an Orten mit Erdstrahlen zuverlässig aus, wäre die Begründung belegt.","Der Begriff „Erdstrahlen“ ist zu unscharf; mit einer genaueren Beschreibung wäre die Begründung in Ordnung.","Die Begründung stützt sich auf eine unsichtbare Kraft; was niemand sehen kann, taugt kaum als Erklärung."],"correctIndex":0,"explanation":"Die Wirkung der Rute wird mit Erdstrahlen erklärt, und Erdstrahlen werden nur darüber bestimmt, dass die Rute auf sie reagiert. Beide Behauptungen stützen sich gegenseitig, und es fehlt der Anker in der überprüfbaren Realität: ein Beleg für eines von beiden, der nichts mit dem anderen zu tun hat. Das ist ein Zirkelschluss (petitio principii): Die Begründung setzt voraus, was sie begründen soll. Auch eine genauere Definition würde den Kreis nicht öffnen, solange sie sich wieder nur auf die Rute beruft. Und unsichtbare Dinge sind nicht grundsätzlich verboten, denn Elektronen sind auch unsichtbar. Entscheidend ist, ob es unabhängige Belege gibt, etwa Messungen, die nicht von der Rute abhängen.","coreRule":"⚡ Frag nach einem Beleg für eine der beiden Seiten, der nichts mit der anderen zu tun hat.","beleg":"Werkstück D.3.6 (Anwendung & Relevanz, „Pseudowissenschaft“; Anti-Denkmuster, Skript 2)","status":"entwurf","kurz":"Rute und Erdstrahlen werden nur durch einander erklärt, und für keines von beiden gibt es einen Beleg, der vom anderen unabhängig ist. So setzt die Begründung voraus, was sie zeigen soll: ein Zirkelschluss, der weder durch mehr Schärfe noch durch Unsichtbarkeit zu erklären ist.","prueffrage":"Was erfährst du über Erdstrahlen, wenn du die zweite Antwort in die erste einsetzt?","rueckmeldung":[{"option":1,"text":"Ein Versuch klingt nach dem richtigen Weg. Er belegt aber nur dann etwas, wenn man die Orte mit Erdstrahlen unabhängig von der Rute bestimmen kann; hier sind Erdstrahlen aber nur das, worauf die Rute reagiert."},{"option":2,"text":"Eine genauere Beschreibung wirkt wie die naheliegende Reparatur. Eine Definition ist aber noch kein Beleg: Beruft sie sich wieder nur auf die Rute, bleibt der Kreis geschlossen."},{"option":3,"text":"Unsichtbares wirkt schnell verdächtig, ist aber nicht grundsätzlich unzulässig: Auch Elektronen sieht niemand. Entscheidend ist, ob sich ein Beleg finden lässt, der nicht von der Rute abhängt."}],"familie":"zirkelschluss-erkennen","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Dowden, B.: Fallacies (Abschnitte Begging the Question, Circular Reasoning). Internet Encyclopedia of Philosophy","oeffentlich":true,"url":"https://iep.utm.edu/fallacy/","abruf":"2026-10-12"},{"typ":"url","kurz":"Stanford Encyclopedia of Philosophy: Fallacies (Fassung vom 30.08.2024)","oeffentlich":true,"url":"https://plato.stanford.edu/entries/fallacies/","abruf":"2026-10-12"}],"thema":"Geschichte und Wissenschaft","pruefung":{"lauf":"quiz-audit-v8","modell":"claude-sonnet-5-5","datum":"2026-10-15","urteil":"korrigieren","pruefsumme":"e0312a5d8fed3a1e"}},{"id":"qx-d2-014","clusterId":"D","werkstueckRef":"D.3.6","stufe":2,"question":"Eine Anhängerin sagt: „Unsere Gruppe liegt richtig, weil nur wahre Mitglieder die Wahrheit erkennen, und wer die Wahrheit erkennt, ist ein wahres Mitglied.“ Ein Kritiker wendet ein: „Aber Mitglied X hat Gelder veruntreut.“ Sie antwortet: „Dann war er nie ein wahres Mitglied.“ Welche Analyse beschreibt beide Aussagen der Anhängerin am treffendsten?","options":["Die erste Aussage setzt voraus, was sie beweisen soll, und sichert so die Grundbehauptung ab; die zweite weist einen Einwand ab, indem sie den Begriff „wahres Mitglied“ nachträglich enger zieht.","Die erste Aussage weist einen Einwand ab, indem sie den Begriff „wahres Mitglied“ nachträglich enger zieht; die zweite setzt voraus, was sie beweisen soll, und sichert so die Grundbehauptung ab.","Beide Aussagen haben denselben Fehler, nur in zwei Formulierungen: Die zweite Aussage wiederholt lediglich die erste in anderen Worten.","Beide Aussagen sind keine Fehlschlüsse, weil jede Gruppe das Recht hat, ihre Begriffe selbst festzulegen und gegen Einzelfälle zu verteidigen."],"correctIndex":0,"explanation":"Die erste Aussage ist ein Zirkelschluss: „Wahr ist, was wahre Mitglieder erkennen“ und „wahres Mitglied ist, wer das Wahre erkennt“ stützen sich gegenseitig, ohne dass irgendein Beleg von außen hinzukommt. Die zweite Aussage hat eine andere Funktion: Sie reagiert auf einen konkreten Einwand und rettet die Behauptung, indem der Begriff „wahres Mitglied“ im Nachhinein so definiert wird, dass der Gegenfall nicht mehr zählt (der „Kein wahrer Schotte“-Trick). Die zweite Aussage wiederholt die erste also nicht in anderen Worten, sondern antwortet auf einen Angriff von außen. Es sind zwei verschiedene Fehler: Der eine baut die Struktur des Dogmas, der andere ist die Verteidigungstaktik dagegen. Dass eine Gruppe ihre Begriffe frei setzen darf, ändert nichts daran, dass solche Setzungen nichts beweisen.","coreRule":"⚡ Wer den Beweis in die Behauptung einbaut, baut einen Kreis (Zirkelschluss); wer den Begriff nach dem Einwand enger zieht, verteidigt ihn (Kein wahrer Schotte).","beleg":"Werkstück D.3.6 (Kontext & Tiefe, „Abgrenzung zum Kein wahrer Schotte“; Verbindungen)","status":"entwurf","scenario":"","kurz":"Die erste Aussage stützt sich nur selbst: Die Wahrheit erkennen nur wahre Mitglieder, und wahres Mitglied ist, wer die Wahrheit erkennt. Die zweite zieht den Begriff erst nach dem Einwand enger. Das sind zwei Fehler: ein Zirkel und eine nachträgliche Rettung.","prueffrage":"Was müsste die Anhängerin vorlegen, damit ein Außenstehender ihre Grundbehauptung prüfen kann?","rueckmeldung":[{"option":1,"text":"Die Reihenfolge im Gespräch spricht dagegen: Der Einwand kommt erst, nachdem der erste Satz gefallen ist, also kann dieser ihn gar nicht abwehren. Erst die Antwort „nie ein wahres Mitglied“ zieht den Begriff nachträglich enger."},{"option":2,"text":"Beide Sätze schützen die Gruppe, das stimmt. Die zweite Aussage wiederholt die erste aber nicht, sondern antwortet auf einen konkreten Angriff von außen. Es sind zwei verschiedene Fehler: der eine baut das Dogma, der andere verteidigt es."},{"option":3,"text":"Begriffe zu setzen steht jeder Gruppe frei, aber solche Setzungen beweisen nichts. Hier stützt der erste Satz sich nur selbst, und im zweiten wird die Definition erst nach dem Einwand so zugeschnitten, dass der Gegenfall nicht mehr zählt."}],"familie":"zirkelschluss-erkennen","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Dowden, B.: Fallacies (Abschnitte Circular Reasoning, No True Scotsman). Internet Encyclopedia of Philosophy","oeffentlich":true,"url":"https://iep.utm.edu/fallacy/","abruf":"2026-10-12"}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"2b7917e70b419d2d"}},{"id":"qx-d2-015","clusterId":"D","werkstueckRef":"D.3.6","stufe":3,"question":"Ein Kollege argumentiert: „Meine Methode ist zuverlässig. Warum? Weil sie funktioniert – und dass sie funktioniert, sieht man daran, dass sie zuverlässig ist.“ Du entgegnest, das sei ein Zirkelschluss. Er kontert: „Aber logisch ist das einwandfrei: Wenn die Prämisse stimmt, stimmt auch die Schlussfolgerung.“ Warum ändert dieser Einwand nichts daran, dass das Argument nichts beweist?","options":["Weil ein Zirkelschluss schon formal ungültig ist; der Kollege irrt also, wenn er die Logik seines Arguments für einwandfrei hält.","Weil Logik nur die Form eines Arguments prüft; ob eine Methode in der Praxis taugt, klärt erst die Erfahrung, nicht die Logik.","Weil der Schluss zwar gültig ist, die Prämisse aber nicht besser gestützt ist als die Konklusion, die sie stützen soll.","Weil ein gültiger Schluss nur zeigt, dass die Konklusion denkbar ist; wahr ist sie damit noch nicht, selbst wenn die Prämisse stimmt."],"correctIndex":2,"explanation":"Gültigkeit und Beweiskraft sind zwei verschiedene Dinge. „P, also P“ ist formal gültig: Wenn die Prämisse stimmt, stimmt auch die Konklusion. Aber die Prämisse taugt nur so viel wie die Konklusion, die sie stützen soll – hier sagt sie schlicht dasselbe in anderen Worten. Ein solches Argument predigt nur zu denen, die bereits glauben. Der Einwand des Kollegen trifft also ins Leere: Die Form ist in Ordnung, aber es fehlt ein unabhängiger, externer Anker, der die Prämisse trägt.","coreRule":"⚡ Gültig ist nicht beweisend: Ein Schluss, der sein Ergebnis voraussetzt, überzeugt nur Überzeugte.","beleg":"Werkstück D.3.6 (Kontext & Tiefe, „Logische Form“ und „Mechanik des Beweisgrund-Erschleichens“)","status":"entwurf","scenario":"","kurz":"Der Schluss ist formal gültig, aber die Prämisse sagt nur dasselbe wie die Konklusion und ist nicht unabhängig gestützt. Der naheliegende Fehler: Gültige Form mit Beweiskraft zu verwechseln.","prueffrage":"Was müsste der Kollege zusätzlich vorlegen, damit jemand, der an der Methode zweifelt, überzeugt wäre?","rueckmeldung":[{"option":0,"text":"Der Schluss „P, also P“ ist formal gültig: Wenn die Prämisse stimmt, stimmt auch die Konklusion. Mit der Form hat der Kollege also recht; das Problem liegt bei der Stütze der Prämisse, nicht bei der Logik."},{"option":1,"text":"Daran stimmt: Die Logik prüft nur die Form, ob eine Methode taugt, zeigt erst die Erfahrung. Das erklärt aber nicht, warum dieses Argument nichts beweist, denn hier fehlt kein Erfahrungswert, sondern eine Prämisse, die mehr sagt als die Konklusion."},{"option":3,"text":"Bei einem gültigen Schluss ist die Konklusion mehr als bloß denkbar: Stimmt die Prämisse, dann stimmt sie zwingend mit. Offen bleibt, ob die Prämisse stimmt, und gerade dafür liefert das Argument keine unabhängige Stütze."}],"familie":"zirkelschluss-erkennen","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Stanford Encyclopedia of Philosophy: Fallacies (Fassung vom 30.08.2024)","oeffentlich":true,"url":"https://plato.stanford.edu/entries/fallacies/","abruf":"2026-10-12"},{"typ":"doi","kurz":"Hahn, U.; Oaksford, M. (2006): A Normative Theory of Argument Strength. Informal Logic 26(1), 1–24","oeffentlich":true,"doi":"10.22329/il.v26i1.428","seite":"16–17","abruf":"2026-10-12"}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v8","modell":"claude-sonnet-5-5","datum":"2026-10-15","urteil":"korrigieren","pruefsumme":"c563d3915f08738c"}},{"id":"qx-d2-016","clusterId":"D","werkstueckRef":"D.3.6","stufe":4,"question":"Beide Argumente sind gleich gebaut. Worin liegt trotzdem der entscheidende Unterschied?","scenario":"Zwei Argumente im Vergleich:\\n\\n(1) „Elektronen gibt es, denn in der Nebelkammer sehen wir Spuren, und solche Spuren sind die Signatur von Elektronen.“\\n\\n(2) „Gott existiert, denn die Bibel sagt es, und die Bibel ist Gottes Wort.“\\n\\nBeide Male wird die Behauptung teilweise schon in der Begründung vorausgesetzt.","options":["Beim Elektronen-Argument sind andere Deutungen der Spuren sehr unwahrscheinlich, beim Bibel-Argument gibt es viele plausible andere Deutungen.","Beim Elektronen-Argument wird die Behauptung nur teilweise vorausgesetzt, beim Bibel-Argument vollständig, deshalb ist nur das zweite zirkulär.","Beim Elektronen-Argument liefern Messgeräte die Belege, beim Bibel-Argument ein Text, und Messdaten sind schon wegen ihrer Art stärker.","Beim Elektronen-Argument stimmen heute fast alle Fachleute zu, beim Bibel-Argument nicht, und diese Zustimmung allein macht das Argument stärker."],"correctIndex":0,"explanation":"Nicht jede stillschweigende Voraussetzung ist ein Fehlschluss. Auch in der Wissenschaft wird überall dort, wo Dinge nicht direkt beobachtbar sind, auf die beste Erklärung geschlossen, und dieser Schluss hat dieselbe Form wie das zweite Argument. Den Unterschied machen die Wahrscheinlichkeiten: Für die Bibel gibt es viele andere plausible Deutungen, als dass sie Gottes Wort ist; beim Elektronen-Schluss ist das nicht der Fall. Untersuchungen zur Stärke von Argumenten (Hahn und Oaksford, 2006, 2007) zeigen, dass dieselbe Argumentform je nach Inhalt unterschiedlich stark sein kann.","coreRule":"⚡ Gleiche Form heißt nicht gleiche Beweiskraft: Frag, wie plausibel die Alternativen zur vorgeschlagenen Erklärung sind.","beleg":"Werkstück D.3.6 (Der Kipppunkt); Fn. gl-d-hahn (Hahn/Oaksford 2006, S. 16–17)","status":"entwurf","kurz":"Beide Argumente schließen auf die beste Erklärung, und das ist an sich legitim. Entscheidend ist, wie viele andere plausible Deutungen es gibt: bei den Nebelkammer-Spuren kaum, bei der Bibel viele. Gleiche Form, unterschiedliche Stärke.","prueffrage":"Wenn Fachleute die Spuren in der Nebelkammer und den Bibeltext untersuchen: Wie einig sind sie sich jeweils über deren Herkunft?","rueckmeldung":[{"option":1,"text":"Dass die Begründung die Behauptung schon halb enthält, erscheint beim zweiten Argument stärker. Laut Szenario steckt sie aber in beiden Fällen teilweise darin, und eine solche Voraussetzung ist nicht von selbst ein Fehler."},{"option":2,"text":"Messdaten sind oft verlässlich, deshalb liegt die Antwort nahe. Die Art der Quelle entscheidet aber nicht über die Stärke: Es kommt darauf an, wie gut andere Deutungen der Belege ausgeschlossen werden können."},{"option":3,"text":"Breite Zustimmung kann ein Hinweis auf gute Belege sein. Sie ist aber eher Folge starker Belege als deren Grund und macht ein Argument nicht für sich genommen stärker."}],"familie":"sparsamste-erklaerung","fertigkeit":"F4","quellen":[{"typ":"doi","kurz":"Hahn, U.; Oaksford, M. (2006): A Normative Theory of Argument Strength. Informal Logic 26(1), 1–24","oeffentlich":true,"doi":"10.22329/il.v26i1.428","seite":"16–17","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Hahn, U.; Oaksford, M. (2007): The Rationality of Informal Argumentation: A Bayesian Approach to Reasoning Fallacies. Psychological Review 114(3), 704–732","oeffentlich":false}],"thema":"Geschichte und Wissenschaft","pruefung":{"lauf":"quiz-audit-v5","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"bcdfc8b51404ee3f"}},{"id":"qx-d2-017","clusterId":"D","werkstueckRef":"D.3.7","stufe":1,"question":"Wie beurteilst du die beiden Wortmeldungen, und was sollte das Team daraus machen?","options":["Beide schließen nur von der Herkunft auf das Ergebnis; das Team sollte die Studie lesen und das Pharma-Geld höchstens als Anlass nehmen, Methode und Daten besonders genau zu prüfen.","Nur Frau Okafor schließt vorschnell, denn ein Universitätsname belegt kein Ergebnis; das Team sollte die Studie wegen des Pharma-Geldes vorerst beiseitelegen, bis eine unabhängige vorliegt.","Nur Herr Brandt schließt vorschnell, denn ein Geldgeber sagt nichts über ein Ergebnis; das Team sollte der Studie wegen der renommierten Universität vorerst vertrauen und sie aufnehmen.","Beide nennen einen sachlichen Umstand der Studie; das Team sollte abwägen, ob das Pharma-Geld oder der Ruf der Universität schwerer wiegt, und je nach Ergebnis aufnehmen oder verwerfen."],"correctIndex":0,"explanation":"Herr Brandt und Frau Okafor schließen allein von der Herkunft auf die Wahrheit, ohne Inhalt, Logik oder Evidenz anzusehen; gelesen hat die Studie ja noch niemand. Herr Brandt macht den genetischen Fehlschluss („schlechte Quelle, also falsch“), Frau Okafor den Appell an die Autorität („gute Quelle, also wahr“); beide Fehler sind spiegelbildlich gebaut. Eine schlechte Bilanz der Quelle darf Anlass sein, besonders kritisch zu prüfen, ein guter Ruf Anlass zu Vertrauen, die Prüfung der Belege ersetzen kann aber beides nicht. Ein sauberes Ergebnis bleibt sauber, auch wenn ein Konzern es bezahlt hat, und ein schwaches wird durch den Namen einer Universität nicht stärker. Jeweils nur einen der beiden zu rügen, klingt ausgewogen, übernimmt aber das Herkunftsurteil des anderen. Und Geldgeber gegen Universitätsruf abzuwägen, wirkt sachlich, bleibt aber ein Vergleich zweier Etiketten, in dem die Studie selbst nicht vorkommt.","coreRule":"⚡ Prüfe den Inhalt, nicht das Etikett der Herkunft, in beide Richtungen.","beleg":"Werkstück D.3.7 (Kernidee)","status":"entwurf","scenario":"Ein Team soll entscheiden, ob es eine neue Studie zu einem Schmerzmittel in seine Empfehlungen aufnimmt. Gelesen hat sie noch niemand. Herr Brandt sagt: „Die Studie ist von einem Pharmakonzern bezahlt, also ist ihr Ergebnis falsch.“ Frau Okafor sagt: „Die Studie stammt von einer renommierten Universität, also ist ihr Ergebnis richtig.“","kurz":"Beide urteilen über eine ungelesene Studie nur nach ihrer Herkunft. Geldgeber oder Ruf dürfen Anlass sein, genauer hinzusehen, ersetzen aber nicht die Prüfung von Methode und Daten; erst die entscheidet, was die Studie wert ist.","prueffrage":"Was an der Studie selbst, nicht an ihrer Herkunft, haben Herr Brandt und Frau Okafor bisher angesehen?","rueckmeldung":[{"option":1,"text":"Dass ein Universitätsname kein Ergebnis belegt, stimmt. Wer die Studie aber wegen des Geldgebers beiseitelegt, urteilt genauso nach Herkunft wie Herr Brandt, nur in die andere Richtung."},{"option":2,"text":"Dass ein Geldgeber allein nichts über ein Ergebnis sagt, stimmt. Dem Ruf der Universität zu vertrauen, ist aber derselbe Schluss von der Herkunft, nur mit umgekehrtem Vorzeichen; geprüft wäre damit nichts."},{"option":3,"text":"Geldgeber und Universität sind tatsächlich Umstände der Studie, und der Geldgeber darf zu genauerem Hinsehen anregen. Beide gegeneinander abzuwägen, vergleicht aber nur zwei Etiketten, während die Studie selbst gar nicht vorkommt."}],"familie":"inhalt-statt-absender","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Internet Encyclopedia of Philosophy: „Fallacies“ (Einträge „Genetic Fallacy“, „Appeal to Authority“)","oeffentlich":true,"url":"https://iep.utm.edu/fallacy/","abruf":"2026-10-12"}],"thema":"Geschichte und Wissenschaft","pruefung":{"lauf":"quiz-audit-v4","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"2e151c3e2d46c133"}},{"id":"qx-d2-018","clusterId":"D","werkstueckRef":"D.3.7","stufe":2,"question":"Welche Rückfrage prüft diese Behauptung am besten?","scenario":"In einer Diskussion über ein Förderprogramm sagt jemand: „Die Grundidee dieses Programms stammt ursprünglich von einer Lobbygruppe. Deshalb ist sie falsch, egal ob die Daten dazu etwas anderes zeigen.“ Die Daten zu dem Programm hat er sich nicht angesehen.","options":["Wie belastbar sind die Daten zum Programm, wenn du sie unabhängig davon betrachtest, wer die Grundidee zuerst entwickelt hat?","Woher weißt du, dass die Grundidee tatsächlich von der Lobbygruppe stammt, und gibt es dafür eine verlässliche Quelle?","Würde die Lobbygruppe von dem Programm profitieren, und hat sie die Grundidee vielleicht genau deshalb vorgeschlagen?","Wie viel ist von der Lobbygruppe im heutigen Programm noch übrig, oder wurde die Grundidee inzwischen umgearbeitet?"],"correctIndex":0,"explanation":"Der Einwand verwirft eine Idee allein wegen ihres Ursprungs. Ob sie stimmt, hängt aber an Inhalt, Logik und Evidenz, nicht daran, wer sie zuerst hatte; deshalb lenkt die beste Rückfrage auf die Daten und trennt sie von der Herkunft. Der Ursprung darf ein Anlass sein, genauer hinzuschauen und nach unabhängiger Bestätigung zu suchen, als Urteil über die Wahrheit taugt er nicht. Ein einfacher Prüftest: Stell dir vor, dieselbe Information stünde anonym auf einem Zettel, und bewerte dann die Belege.","coreRule":"⚡ Ursprung einer Idee ist ein Anlass zum Prüfen, kein Urteil.","beleg":"Werkstück D.3.7 (Kontext & Tiefe, „Abgrenzung zum Ad Hominem“)","status":"entwurf","kurz":"Ob ein Programm wirkt, zeigen die Daten, nicht die Herkunft seiner Grundidee. Wer die Idee wegen ihres Ursprungs verwirft, ohne die Belege anzusehen, urteilt über die Quelle statt über die Sache.","prueffrage":"Worauf stützt der Sprecher sein Urteil „falsch“, und was hat er sich dafür selbst angesehen?","rueckmeldung":[{"option":1,"text":"Die Herkunft zu klären ist sinnvoll und kann ein Anlass sein, genauer hinzusehen. Selbst eine bestätigte Herkunft sagt aber nichts darüber, ob die Idee stimmt, der Schluss auf „falsch“ bliebe ungeprüft."},{"option":2,"text":"Eine mögliche Interessenlage kann zu genauerem Hinschauen anregen. Ob jemand von einer Idee profitiert, entscheidet aber nicht darüber, ob sie stimmt; das zeigen nur Inhalt und Belege."},{"option":3,"text":"Dass sich die Idee verändert haben könnte, klingt nach einer Prüfung. Sie bleibt aber beim Ursprung: Auch eine unveränderte Idee wäre nicht schon deshalb falsch, und gefragt ist, was die Daten zeigen."}],"familie":"inhalt-statt-absender","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Internet Encyclopedia of Philosophy: „Fallacies“ (Eintrag „Genetic Fallacy“)","oeffentlich":true,"url":"https://iep.utm.edu/fallacy/","abruf":"2026-10-12"}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v8","modell":"claude-sonnet-5-5","datum":"2026-10-15","urteil":"korrigieren","pruefsumme":"ddc7e3db43527f75"}},{"id":"qx-d2-019","clusterId":"D","werkstueckRef":"D.3.7","stufe":3,"question":"Welche Reaktion ist hier vernünftig, ohne in einen Denkfehler zu kippen?","scenario":"Dir liegt eine Studie vor, die von einem Konzern finanziert wurde, dem du misstraust. Du weißt, dass solche Auftraggeber in der Vergangenheit Studien manipuliert haben. Ein Bekannter sagt: „Die Studie kannst du dir sparen, die ist von denen bezahlt.“","options":["Die Studie erst dann misstrauisch lesen, wenn sich in ihr selbst Widersprüche zeigen, denn ohne Widerspruch fehlt jeder Anlass.","Die Studie wie jede andere behandeln und die Vorgeschichte des Konzerns ausblenden, denn sie lässt keinen Schluss auf diese Studie zu.","Die Studie besonders genau prüfen und nach unabhängiger Bestätigung suchen, denn die schlechte Bilanz des Konzerns verlangt mehr Sorgfalt.","Die Studie ungelesen beiseitelegen, bis eine unabhängige Stelle sie bestätigt, denn bei diesem Geldgeber lohnt die Lektüre vorher nicht."],"correctIndex":2,"explanation":"Misstrauen gegenüber einer Quelle mit schlechter Bilanz ist berechtigt, solange es dazu führt, die Studie besonders kritisch zu prüfen und nach unabhängiger Bestätigung zu suchen. Zum Fehlschluss wird es, wenn die Herkunft allein als Beweis gegen den Inhalt gilt („von denen bezahlt, also falsch“, der genetische Fehlschluss). Eine Idee ist an Inhalt, Logik und Evidenz zu bewerten, nicht an ihrem Ursprung. Erst bei sichtbaren Widersprüchen misstrauisch zu werden übersieht, dass die Vorgeschichte hier schon Grund zur Sorgfalt gibt. Die Vorgeschichte einfach auszublenden verschenkt genau diesen Hinweis. Und die Studie ungelesen wegzulegen, bis jemand sie bestätigt, ist der Fehlschluss selbst: Die Herkunft ersetzt dann die Prüfung des Inhalts.","coreRule":"⚡ Schlechte Bilanz heißt: genauer prüfen, nicht: ungelesen verwerfen.","beleg":"Werkstück D.3.7 (Der Kipppunkt)","status":"entwurf","kurz":"Die schlechte Bilanz des Geldgebers ist ein Grund, genauer hinzusehen und unabhängige Bestätigung zu suchen. Zum Fehlschluss wird sie erst, wenn die Herkunft allein den Inhalt entscheiden soll („von denen bezahlt, also falsch“).","prueffrage":"Was weißt du über diese konkrete Studie bisher, außer wer sie bezahlt hat?","rueckmeldung":[{"option":0,"text":"Gelesen wird die Studie hier ohnehin, und ein Urteil allein nach der Herkunft wäre verfrüht. Warten, bis sich Widersprüche zeigen, übersieht aber, dass die Vorgeschichte schon jetzt Grund zur Sorgfalt gibt."},{"option":1,"text":"Die Herkunft allein belegt tatsächlich nicht, dass diese Studie falsch ist. Sie völlig auszublenden verschenkt aber einen berechtigten Hinweis: Er spricht nicht gegen den Inhalt, wohl aber für genaueres Prüfen."},{"option":3,"text":"Unabhängige Bestätigung zu suchen ist sinnvoll. Wer die Studie dafür ungelesen weglegt, lässt aber die Herkunft die Prüfung ersetzen. Genau das ist der Fehlschluss: Der Inhalt wird gar nicht erst angeschaut."}],"familie":"inhalt-statt-absender","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Internet Encyclopedia of Philosophy: „Fallacies“ (Einträge „Genetic Fallacy“, „Appeal to Authority“)","oeffentlich":true,"url":"https://iep.utm.edu/fallacy/","abruf":"2026-10-12"}],"thema":"Geschichte und Wissenschaft","pruefung":{"lauf":"quiz-audit-v4","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"ok","pruefsumme":"4124321b3fb9c77c"}},{"id":"qx-d2-020","clusterId":"D","werkstueckRef":"D.3.7","stufe":4,"question":"Welcher Schritt hilft dir am besten, die Bewertung des Punktes vom Absender zu trennen?","scenario":"Ein Gesetzesvorschlag der Partei, die du ablehnst, enthält einen Punkt, der dir eigentlich einleuchtet. Du merkst, dass du ihn vor allem wegen des Absenders ablehnen willst.","options":["Nachsehen, ob die Partei den Punkt früher selbst abgelehnt hat, und dein Urteil davon abhängig machen, wie konsequent sie bisher gehandelt hat.","Den Punkt mit dem Wahlprogramm der Partei vergleichen, um zu sehen, ob er zu ihrer Linie passt, und danach entscheiden, wie ernst er gemeint ist.","Eine Nacht darüber schlafen, bis sich dein Ärger über die Partei gelegt hat, und den Punkt danach noch einmal wie gewohnt lesen.","Dir den Punkt ohne Absender oder als Vorschlag einer Seite vorstellen, der du vertraust, und prüfen, ob sich dein Urteil über den Inhalt dann ändert."],"correctIndex":3,"explanation":"Deine Ablehnung gilt hier dem Absender, nicht dem Inhalt. Das ist ein genetischer Fehlschluss: Ob ein Vorschlag sinnvoll ist, hängt an Inhalt, Logik und Evidenz, nicht an seinem Ursprung. Der Gedankentest mit fehlendem oder vertauschtem Absender löst die Bewertung vom Ursprung und zeigt, ob du den Inhalt oder nur den Absender beurteilst. Zu prüfen, wie konsequent die Partei bisher war oder ob der Punkt zu ihrem Wahlprogramm passt, bleibt beim Absender und sagt nichts über den Inhalt. Und zu warten, bis sich der Ärger legt, ändert nichts daran, woran du den Punkt misst.","coreRule":"⚡ Stell dir die Information anonym vor: Hält der Inhalt dann stand?","beleg":"Werkstück D.3.7 (Anti-Denkmuster, Skript 1; Anwendung & Relevanz, „Politische Ideologie“)","status":"entwurf","kurz":"Ob ein Vorschlag taugt, hängt an Inhalt, Logik und Belegen, nicht an seiner Herkunft. Wer ihn gedanklich von seinem Absender löst, sieht, ob das Urteil dem Inhalt gilt oder nur dem Absender, und verhindert so einen genetischen Fehlschluss.","prueffrage":"Welche Gründe gegen den Punkt selbst fallen dir ein, die nichts mit der Partei zu tun haben?","rueckmeldung":[{"option":0,"text":"Wie konsequent die Partei früher handelte, sagt etwas über ihre Glaubwürdigkeit. Das ist eine andere Frage als die nach dem Punkt selbst, dessen Wert vom Vorschlagenden unabhängig bleibt."},{"option":1,"text":"Das Wahlprogramm zeigt, wie ernst der Vorschlag gemeint sein könnte. Es sagt aber nichts darüber, ob der Punkt sinnvoll ist, und führt dich wieder zum Absender statt zum Inhalt."},{"option":2,"text":"Mit weniger Ärger liest du vermutlich ruhiger. Gemessen wird der Punkt danach aber noch immer am selben Maßstab, und der Absender bleibt im Hintergrund präsent, wenn du ihn nicht bewusst ausblendest."}],"familie":"inhalt-statt-absender","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Internet Encyclopedia of Philosophy: „Fallacies“ (Eintrag „Genetic Fallacy“)","oeffentlich":true,"url":"https://iep.utm.edu/fallacy/","abruf":"2026-10-12"}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v4","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"ok","pruefsumme":"b3ef33860c7d0fde"}},{"id":"qx-d2-021","clusterId":"D","werkstueckRef":"D.3.8","stufe":1,"question":"Was ist an diesem Schluss logisch fehlerhaft?","scenario":"Auf einer Podiumsdiskussion verteidigt ein Erfinder sein Perpetuum mobile gegen die Kritik von Physikern: „Jede große Wahrheit wurde zuerst bekämpft. Meine Maschine wird bekämpft. Also steckt eine große Wahrheit darin.“","options":["Er kehrt eine Aussage um: Aus „Große Wahrheiten wurden zuerst bekämpft“ folgt nicht „Alles, was bekämpft wird, ist eine große Wahrheit“.","Er verwendet „bekämpft“ in zwei Bedeutungen: Die Unterdrückung früherer Wahrheiten und die Kritik von Physikern an einer Maschine sind nicht dasselbe.","Er schließt von früher auf heute: Dass große Wahrheiten einst bekämpft wurden, heißt nicht, dass Fachleute heute noch genauso mit Neuem umgehen.","Er deutet das Urteil der Fachleute um: Dass Physiker ihm widersprechen, wertet er als Pluspunkt, obwohl ihr Einwand eher gegen die Maschine spricht."],"correctIndex":0,"explanation":"Der Schluss hat die Form „Alle A sind B, dies ist B, also ist dies A“: Aus „Große Wahrheiten wurden bekämpft“ folgt nicht „Alles Bekämpfte ist eine große Wahrheit“. Carl Sagan nennt Fulton und die Brüder Wright als Verlachte, aber auch Bozo den Clown. Ablehnung trifft Genies und Irrtümer gleichermaßen und unterscheidet beide deshalb nicht. Eine Autorität beruft der Erfinder nicht an, einen Beleg ersetzt er also auch nicht auf diese Weise. Die Beweislast schiebt er den Physikern nicht zu, er fordert von ihnen nichts. Und ein Zirkel liegt nicht vor, weil die Schlussfolgerung in der ersten Aussage noch nicht steckt.","coreRule":"⚡ Dass manche Genies verlacht wurden, macht nicht jeden Verlachten zum Genie.","beleg":"Werkstück D.3.8 (Kernidee)","status":"entwurf","quote":"","quoteLabel":"","kurz":"Aus „Große Wahrheiten wurden bekämpft“ folgt nicht „Was bekämpft wird, ist eine große Wahrheit“. Ablehnung trifft Genies wie Irrtümer, also unterscheidet sie beide nicht. Der Fehler liegt in der vertauschten Richtung des Schlusses.","prueffrage":"Wird nur Richtiges abgelehnt, oder gibt es auch abgelehnte Ideen, die sich später als Irrtum erwiesen?","rueckmeldung":[{"option":1,"text":"Das Wort „bekämpft“ meint in beiden Sätzen im Kern dasselbe: Ablehnung. Ein Unterschied in der Schärfe besteht, aber er trägt den Fehler nicht. Der Schluss wäre auch bei gleichem Wortsinn ungültig."},{"option":2,"text":"Ob Fachleute heute anders mit Neuem umgehen, ist eine eigene Frage. Der Schluss wäre auch dann fehlerhaft, wenn sie sich genau wie früher verhielten, denn sein Fehler liegt in der Form, nicht im Zeitabstand."},{"option":3,"text":"Der Erfinder nutzt den Widerspruch tatsächlich als Stütze für seine Sache. Das erklärt aber nicht, warum der Schluss ungültig ist: Der Fehler liegt in der Form des Arguments, nicht darin, wie er den Einwand der Physiker bewertet."}],"familie":"ablehnung-ist-kein-beleg","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Internet Encyclopedia of Philosophy: „Fallacies“ (Einträge „Affirming the Consequent“, „Undistributed Middle“)","oeffentlich":true,"url":"https://iep.utm.edu/fallacy/","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Sagan, C. (1979): Broca's Brain, Kap. 5 „Night Walkers and Mystery Mongers“","oeffentlich":false}],"thema":"Geschichte und Wissenschaft","pruefung":{"lauf":"quiz-audit-v8","modell":"claude-sonnet-5-5","datum":"2026-10-15","urteil":"korrigieren","pruefsumme":"613ff5e70b417fa1"}},{"id":"qx-d2-022","clusterId":"D","werkstueckRef":"D.3.8","stufe":2,"question":"Was ist an diesem Schluss fehlerhaft?","options":["Aus „Manche echten Neuerer wurden zunächst abgelehnt“ folgt nicht „Wer abgelehnt wird, ist ein echter Neuerer“.","Aus „Galilei wurde verlacht und hatte am Ende recht“ folgt nicht „Meine Theorie ist so gut begründet wie seine“.","Aus „Meine Theorie wird von allen Fachleuten abgelehnt“ folgt nicht „Die Frage nach meinen Daten ist beantwortet“.","Aus „Über Galilei haben sie auch gelacht“ folgt nicht „Galileis Ansehen spricht auch für meine Theorie“."],"correctIndex":0,"explanation":"Der Schluss kehrt eine wahre Aussage unzulässig um: Dass einige Genies zunächst abgelehnt wurden, heißt nicht, dass jeder Abgelehnte ein Genie ist. Abgelehnt werden auch unzählige Theorien, die sich als falsch erweisen, nur bleiben sie nicht in Erinnerung, weil niemand ihre Geschichten erzählt. Ablehnung trifft Genie und Irrtum gleichermaßen und trennt beide deshalb nicht, ganz gleich, aus wie vielen Fachrichtungen sie kommt. Entscheidend ist, ob die Theorie prüfbare Belege oder Vorhersagen liefert, so wie Galilei Beobachtungen hatte, die jeder mit einem Fernrohr nachprüfen konnte.","coreRule":"⚡ Ablehnung allein beweist nichts: Zähle auch die Bozos, nicht nur die Galileis, und frage nach prüfbaren Belegen.","beleg":"Werkstück D.3.8 (Kontext & Tiefe, „Die Basisrate wird unterschlagen“; Das Adaptive Talent)","status":"entwurf","scenario":"Auf einer Veranstaltung stellt ein Redner seine neue Theorie über die Ursache einer Krankheit vor. Nach Belegen gefragt, legt er keine eigenen Daten vor und sagt: „Meine Theorie wird von allen Fachleuten abgelehnt. Das zeigt, dass ich ein Genie bin – über Galilei haben sie auch gelacht.“","quote":"","quoteLabel":"","kurz":"Dass einige Neuerer zunächst abgelehnt wurden, heißt nicht, dass jeder Abgelehnte ein Neuerer ist. Abgelehnt werden auch unzählige falsche Theorien, nur erinnert sich niemand an sie, deshalb trennt Ablehnung Genie und Irrtum nicht.","prueffrage":"Wie viele abgelehnte Theorien kennst du, die sich später als falsch erwiesen haben, und wer erzählt ihre Geschichten?","rueckmeldung":[{"option":1,"text":"Dass Galilei Beobachtungen hatte, die jeder nachprüfen konnte, während der Redner keine Daten zeigt, stimmt. Der Fehler im Schluss liegt aber früher: Aus „abgelehnt“ wird „Genie“, obwohl Ablehnung beide Fälle trifft."},{"option":2,"text":"Dass Ablehnung keine fehlenden Daten ersetzt, ist richtig. Der Redner behauptet aber nicht, damit die Datenfrage beantwortet zu haben, sondern leitet aus der Ablehnung seine Genialität ab. Dieser Schritt ist der fehlerhafte."},{"option":3,"text":"Hier klingt die Berufung auf Galileis Ansehen mit. Der Redner leiht sich aber kein Ansehen, sondern zieht aus dem gemeinsamen Verlachtwerden einen Schluss auf sich. Fehlerhaft ist diese Umkehrung, nicht eine Ansehensübertragung."}],"familie":"ablehnung-ist-kein-beleg","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Miller, D. M. (Rev. 2025): „Galileo Galilei“, Stanford Encyclopedia of Philosophy","oeffentlich":true,"url":"https://plato.stanford.edu/entries/galileo/","abruf":"2026-10-12"},{"typ":"url","kurz":"Internet Encyclopedia of Philosophy: „Fallacies“ (Eintrag „Affirming the Consequent“)","oeffentlich":true,"url":"https://iep.utm.edu/fallacy/","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Sagan, C. (1979): Broca's Brain, Kap. 5","oeffentlich":false}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v8","modell":"claude-sonnet-5-5","datum":"2026-10-15","urteil":"korrigieren","pruefsumme":"8f5469883a223168"}},{"id":"qx-d2-023","clusterId":"D","werkstueckRef":"D.3.8","stufe":3,"question":"Welche Rückfrage trifft die Schwäche des Vergleichs am besten?","scenario":"In einer Diskussion über eine neue „Ursache“ einer Krankheit sagt ein Redner: „Die Fachleute lehnen meine These ab. Genau wie bei Galilei: Der wurde von den Gelehrten seiner Zeit verfolgt, und am Ende hatte er recht.“ Du willst prüfen, ob dieser Vergleich trägt.","options":["Welche Vorhersage deiner These zur Krankheitsursache kann jeder unabhängig überprüfen?","Welche Ausbildung hast du, und was hast du bisher zu dieser Krankheit erforscht?","Wer verdient daran, wenn sich deine These zur Ursache verbreitet, und wer verliert?","Wie viele Betroffene haben mit deiner Erklärung der Krankheit schon gute Erfahrungen gemacht?"],"correctIndex":0,"explanation":"Der Vergleich schließt von „Galilei wurde abgelehnt und hatte recht“ auf „ich werde abgelehnt, also habe ich recht“. Das ist ein ungültiger Umkehrschluss: Dass manche Genies abgelehnt wurden, sagt nichts über jeden, der abgelehnt wird, denn auch unzählige falsche Theorien wurden abgelehnt. Ablehnung ist daher kein Beleg, sondern trennt Genie und Irrtum nicht. Entscheidend ist, was die These an Prüfbarem vorlegt. Galilei überzeugte, weil jeder mit einem Fernrohr die Venusphasen und die Jupitermonde sehen konnte. Kepler bestätigte die Monde noch 1610, und die Mathematiker des Jesuitenkollegs in Rom bestätigten 1611 die Venusphasen und die vier Jupitermonde. Die Fachleute prüften also nach und gaben Galilei recht. Verurteilt wurde er erst 1633, und zwar von einer Glaubensbehörde, nicht von einer Fachgemeinschaft. Wer sich auf Galilei beruft, muss deshalb zeigen, was seine eigene These an prüfbaren Belegen hat. Die Rückfrage nach der unabhängig überprüfbaren Vorhersage verlangt genau das und lenkt das Gespräch von der Verfolgung zurück zur Evidenz. Nach Ausbildung oder Verdienst zu fragen betrifft den Redner, nicht den Vergleich, und eine Sammlung guter Erfahrungen ersetzt keine unabhängig überprüfbare Vorhersage.","coreRule":"⚡ Abgelehnt zu werden ist kein Beleg. Entscheidend ist, was andere selbst prüfen können.","beleg":"Werkstück D.3.8 (Kontext & Tiefe, „Die Geschichte wird umgeschrieben“); Fn. gl-d-galileo (Finocchiaro 1989), gl-d-collegio (Favaro 1901, Bd. 11, Nr. 515 und 520, S. 87–88 und 92–93), gl-d-kepler (de Padova 2009). Magini (geprüft 12.10.2026 in Galileo, Le opere, Bd. 10 und 11): Kenntnis der „4 novis planetis“ belegt (Magini an Kepler, 20.4.1610); eigene Aufzeichnung der Monde nicht belegt (Magini an Galilei 23.10.1610: will Linsen erst noch testen; Cigoli an Galilei 23.8.1611: Magini beobachte laut Hörensagen „continuamente“ die vier Jupiterstelle). Halbsatz zu Magini deshalb gestrichen.","status":"entwurf","kurz":"Der Vergleich schließt von „Galilei wurde abgelehnt und hatte recht“ auf „ich werde abgelehnt, also habe ich recht“. Ablehnung trennt Genie und Irrtum nicht; entscheidend ist, was die These an unabhängig Prüfbarem vorlegt.","prueffrage":"Wie viele andere abgelehnte Thesen aus der Geschichte kennst du, die sich am Ende als falsch erwiesen?","rueckmeldung":[{"option":1,"text":"Die Frage nach Ausbildung und Forschung wirkt wie ein fairer Test der Glaubwürdigkeit. Sie zielt aber auf den Redner und nicht auf den Vergleich: Ob die These trägt, zeigen ihre prüfbaren Belege, nicht der Lebenslauf."},{"option":2,"text":"Wer von einer Idee profitiert, wirkt schnell verdächtig. Das sagt aber nichts darüber, ob der Galilei-Vergleich trägt, denn auch eine richtige These kann Gewinner haben. Die Frage betrifft die Motive, nicht die Belege."},{"option":3,"text":"Berichte von Betroffenen klingen nach echter Wirkung. Sie ersetzen aber keine unabhängig überprüfbare Vorhersage, denn gute Erfahrungen können viele andere Gründe haben als die behauptete Ursache."}],"familie":"ablehnung-ist-kein-beleg","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Miller, D. M. (Rev. 2025): „Galileo Galilei“, Stanford Encyclopedia of Philosophy","oeffentlich":true,"url":"https://plato.stanford.edu/entries/galileo/","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Favaro, A. (Hg.) (1901): Le Opere di Galileo Galilei, Ed. Nazionale, Bd. 11, Nr. 515 und 520","oeffentlich":false},{"typ":"literatur","kurz":"de Padova, T. (2009): Das Weltgeheimnis. Kepler, Galilei und die Vermessung des Himmels. München: Piper","oeffentlich":false}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v4","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"77397e39fd35839a"}},{"id":"qx-d2-024","clusterId":"D","werkstueckRef":"D.3.8","stufe":4,"question":"Was macht diese Argumentation unwiderlegbar?","scenario":"Ein „Heiler“, dem die Zulassung entzogen wurde, schreibt: „Wenn es nicht stimmen würde, würden sie sich nicht so viel Mühe geben, es zu unterdrücken.“","options":["Der Heiler lässt offen, wer mit „sie“ gemeint ist: Solange niemand benannt wird, kann man seine Behauptung über die Unterdrückung nicht prüfen.","Der Heiler schließt aus der Mühe der Gegenseite auf ihre Absicht: Was jemanden innerlich antreibt, lässt sich von außen kaum nachprüfen.","Der Heiler sagt nicht, was „es“ genau ist: Ohne beschriebene Methode oder Wirkung gibt es an der Sache selbst nichts, was man überprüfen könnte.","Der Heiler wertet jede Reaktion der Gegenseite als Bestätigung: Zustimmung und Widerstand passen beide gleichermaßen zu seiner These."],"correctIndex":3,"explanation":"Wer Gegenwehr als Beleg wertet, macht seine These unangreifbar: Zustimmung und Ablehnung stützen sie nun gleichermaßen – das ist die vollständige Immunisierung. Eine solche These lässt sich durch keine Reaktion der Gegenseite mehr widerlegen. Die Frage ist also nicht, wie die Kritiker reagieren, sondern welche prüfbare Vorhersage die These macht: Welche Beobachtung würde sie widerlegen? Und was legt der Heiler vor, das andere unabhängig nachprüfen können? Auch Galilei überzeugte nicht durch seine Verfolgung, sondern dadurch, dass jeder durch sein Fernrohr die Jupitermonde und die Venusphasen selbst sehen konnte.","coreRule":"⚡ Eine These, die durch Zustimmung und Ablehnung gleichermaßen bestätigt wird, ist nicht überprüfbar.","beleg":"Werkstück D.3.8 (Anwendung & Relevanz, „Verschwörungsmythen“ und „Pseudomedizin“; Anti-Denkmuster, Skript 2)","status":"entwurf","kurz":"Die These ist unwiderlegbar, weil jede Reaktion als Bestätigung zählt: Gegenwehr gilt als Beweis, Zustimmung natürlich auch. Der Fehler liegt darin, dass keine denkbare Beobachtung die These je widerlegen könnte.","prueffrage":"Wie würde der Heiler es wohl deuten, wenn die Behörden ihn einfach in Ruhe ließen?","rueckmeldung":[{"option":0,"text":"Ein unbenanntes „sie“ macht die Behauptung tatsächlich schwer prüfbar. Doch auch mit klar benannten Gegnern bliebe der Satz unwiderlegbar, weil er ihre Gegenwehr stets als Beleg wertet."},{"option":1,"text":"Die Absicht hinter der Mühe lässt sich von außen kaum prüfen, das stimmt. Unwiderlegbar wird der Satz aber nicht dadurch, sondern weil jede Reaktion der Gegenseite als Bestätigung umgedeutet wird."},{"option":2,"text":"Dass nicht gesagt wird, was „es“ ist, erschwert die Prüfung der Sache. Der Kniff des Satzes liegt aber woanders: Selbst bei genau beschriebener Methode würde Widerstand weiterhin als Beweis gelten."}],"familie":"immunisierung-erkennen","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Hansson, S. O. (Rev. 2025): „Science and Pseudo-Science“, Stanford Encyclopedia of Philosophy","oeffentlich":true,"url":"https://plato.stanford.edu/entries/pseudo-science/","abruf":"2026-10-12"},{"typ":"url","kurz":"Miller, D. M. (Rev. 2025): „Galileo Galilei“, Stanford Encyclopedia of Philosophy","oeffentlich":true,"url":"https://plato.stanford.edu/entries/galileo/","abruf":"2026-10-12"}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v8","modell":"claude-sonnet-5-5","datum":"2026-10-15","urteil":"korrigieren","pruefsumme":"036c2219caa3a471"}},{"id":"qx-d2-025","clusterId":"D","werkstueckRef":"D.3.9","stufe":2,"question":"Was würde am besten klären, ob dein Gegenüber ehrlich nachfragt oder dich nur mit Fragen erschöpfen will?","scenario":"Unter deinem Beitrag zu einem umstrittenen Thema fragt jemand freundlich nach einer Quelle. Du lieferst sie. Die Antwort lautet: „Danke! Und hast du noch eine?“ Du lieferst eine zweite, wieder heißt es „Danke, und noch eine?“ Das wiederholt sich mehrmals, ohne dass je auf den Inhalt der Quellen eingegangen wird.","options":["Beobachten, was nach deiner Antwort geschieht: Arbeitet er mit der Quelle, prüft sie, widerspricht mit Gründen oder ändert etwas, oder folgt nur die nächste Frage?","Auf den Tonfall achten: Bleibt er über alle Runden hinweg freundlich und bedankt sich weiter, spricht das für eine ehrlich gemeinte Nachfrage und gegen bloßes Erschöpfen.","Mitzählen, wie viele Quellen du schon geliefert hast: Je länger die Reihe der Nachfragen wird, desto weniger spricht für ein ehrliches Interesse an der Sache.","Ihn direkt fragen, wozu er die weiteren Quellen braucht: Kann er sein Anliegen verständlich erklären, spricht das für eine ehrliche Nachfrage und gegen bloßes Erschöpfen."],"correctIndex":0,"explanation":"Ob eine Nachfrage ehrlich ist, zeigt sich nicht an der einzelnen Frage, sondern an dem, was nach der Antwort geschieht. Wer wirklich verstehen oder prüfen will, geht auf das Gelieferte ein: Er stimmt zu, widerspricht mit Gründen, benennt, was ihn noch nicht überzeugt, oder ändert seine Meinung. Wer nur die nächste Frage stellt, ohne je etwas anzuerkennen, will nicht prüfen, sondern erschöpfen. Das Muster ist als „Sealioning“ bekannt: höfliche Dauerfragen als Belästigungstaktik. Der Tonfall taugt nicht als Kriterium, denn ausgesuchte Höflichkeit gehört zur Taktik, und freundlich war er hier von Anfang an. Auch eine feste Zahl an Nachfragen taugt nicht: Wer sich in eine Quelle vertieft, fragt vielleicht oft, arbeitet aber mit jeder Antwort.","coreRule":"⚡ Prüf, ob dein Gegenüber mit deiner Antwort arbeitet oder nur die nächste Frage stellt.","beleg":"Werkstück D.3.9 (Der Seelöwe im Wohnzimmer; Kontext & Tiefe, „Die Kultur der Nachfrage“; Red Flags; Anti-Denkmuster, Skript 1; Fußnote gl-d-sealioning, Malki 2014)","status":"entwurf","quote":"","quoteLabel":"","kurz":"Ehrlich nachgefragt wird erkennbar daran, was nach deiner Antwort folgt: Wer prüfen will, geht auf die Quelle ein, widerspricht mit Gründen oder ändert etwas. Aus Tonfall oder Anzahl der Fragen lässt sich das nicht ablesen.","prueffrage":"Würde sich jemand, der ehrlich fragt und sich gründlich einliest, im Ton oder in der Zahl der Fragen von deinem Gegenüber unterscheiden?","rueckmeldung":[{"option":1,"text":"Dass er freundlich bleibt, klingt nach gutem Willen. Als Maßstab hilft es aber nicht, denn ausgesuchte Höflichkeit gehört gerade zu dieser Taktik. Und er war hier von Anfang an freundlich, ohne je auf den Inhalt einzugehen."},{"option":2,"text":"Eine lange Reihe ohne Reaktion auf den Inhalt macht stutzig. Eine feste Zahl entscheidet aber nichts: Wer sich in eine Quelle vertieft, fragt vielleicht oft, arbeitet jedoch mit jeder Antwort. Es zählt, ob er auf das Gelieferte eingeht, nicht die Rundenzahl."},{"option":3,"text":"Direkt nachzufragen ist legitim und kann Hinweise geben. Eine verständlich klingende Begründung lässt sich aber leicht liefern und belegt keine Ehrlichkeit. Aussagekräftiger ist, was er mit deinen Quellen dann tatsächlich tut."}],"familie":"kraefte-und-ausstieg","fertigkeit":"F3","quellen":[{"typ":"url","kurz":"Johnson, A. (2017): „The Multiple Harms of Sea Lions“, in: Perspectives on Harmful Speech Online, Berkman Klein Center, Harvard","oeffentlich":true,"url":"https://cyber.harvard.edu/sites/cyber.harvard.edu/files/2017-08_harmfulspeech.pdf","seite":"S. 13","abruf":"2026-10-12"},{"typ":"url","kurz":"Malki, D. (2014): „The Terrible Sea Lion“, Wondermark Nr. 1062","oeffentlich":true,"url":"https://wondermark.com/c/1062/","abruf":"2026-10-12"}],"thema":"Netz und Medien","pruefung":{"lauf":"quiz-audit-v8","modell":"claude-sonnet-5-5","datum":"2026-10-15","urteil":"korrigieren","pruefsumme":"79adee1de2d824da"}},{"id":"qx-d2-026","clusterId":"D","werkstueckRef":"D.3.9","stufe":3,"question":"Welche der vier Antworten ist eine legitime Nachfrage und kein Sealioning?","options":["„Danke für den Link. Gibt es noch weitere Studien, die das bestätigen? Eine einzelne Studie überzeugt mich ehrlich gesagt noch nicht ganz.“","„Danke. Ich habe die Studie gelesen: Die Teilnehmer waren alle erwachsen. Gilt dein Schluss auch für Kinder, und wenn ja, woraus folgt das?“","„Danke. Kannst du mir kurz in eigenen Worten erklären, was in der Studie genau herauskam? Ich möchte sichergehen, dass ich es richtig verstehe.“","„Danke! Aber Studien widersprechen sich ja oft. Woher weißt du, dass gerade diese stimmt und nicht eine, die zu einem anderen Ergebnis kommt?“"],"correctIndex":1,"explanation":"Eine legitime Nachfrage arbeitet mit der erhaltenen Antwort: Sie knüpft an das an, was der Beleg zeigt, und fragt gezielt nach der Lücke. Die anderen Beiträge klingen höflich und für sich nicht unvernünftig, gehen aber nicht auf das Gelieferte ein. Gerade die höfliche Verpackung macht das gefährlich: Jede einzelne Frage wirkt harmlos, der Schaden wächst mit der Wiederholung, und wer die Geduld verliert, steht als der Unvernünftige da. Der Prüfstein ist nicht die Frage selbst, sondern was nach der Antwort geschieht: Wird mit ihr gearbeitet oder kommt nur die nächste Forderung?","coreRule":"⚡ Eine gute Nachfrage knüpft an deine Antwort an; ein Sealion stellt einfach die nächste Frage.","beleg":"Werkstück D.3.9 (Der Kipppunkt; Der Seelöwe im Wohnzimmer); Fn. gl-d-sealioning (Malki 2014, Wondermark Nr. 1062)","status":"entwurf","scenario":"Du hast unter einem Beitrag zur Wirkung eines Medikaments geschrieben, es habe in einer Studie die Beschwerden verringert. Auf Nachfrage hast du die Studie verlinkt und die Ergebnisse zusammengefasst. Daraufhin kommen vier Antworten.","kurz":"Eine gute Nachfrage arbeitet mit dem Gelieferten: Sie knüpft an die Studie an und fragt gezielt nach einer Lücke, hier der Übertragbarkeit auf Kinder. Sealioning klingt gleich höflich, verlangt aber nur Neues, ohne die Antwort zu verwerten.","prueffrage":"Worauf in der verlinkten Studie bezieht sich jede der vier Antworten, und was verlangt sie von dir?","rueckmeldung":[{"option":0,"text":"Dass eine einzelne Studie begrenzt aussagekräftig ist, stimmt. Die Antwort sagt aber nicht, was an dieser Studie fehlt, und knüpft an nichts darin an. Sie verlangt einfach mehr, und nach der nächsten Studie käme vermutlich die nächste Forderung."},{"option":2,"text":"Verständnisfragen sind grundsätzlich gut. Hier wurde aber schon zusammengefasst und die Studie verlinkt. Die Bitte, es noch einmal zu erklären, ersetzt die eigene Lektüre und trifft keine bestimmte Stelle, die offengeblieben wäre."},{"option":3,"text":"Dass sich Studien widersprechen können, stimmt. Die Frage nennt aber weder einen konkreten Widerspruch noch einen Mangel dieser Studie. Sie verlangt einen Beweis, den niemand abschließend liefern kann, und arbeitet nicht mit dem Gelieferten."}],"familie":"kraefte-und-ausstieg","fertigkeit":"F3","quellen":[{"typ":"url","kurz":"Johnson, A. (2017): „The Multiple Harms of Sea Lions“, in: Perspectives on Harmful Speech Online, Berkman Klein Center, Harvard","oeffentlich":true,"url":"https://cyber.harvard.edu/sites/cyber.harvard.edu/files/2017-08_harmfulspeech.pdf","seite":"S. 13","abruf":"2026-10-12"}],"thema":"Netz und Medien","pruefung":{"lauf":"quiz-audit-v8","modell":"claude-sonnet-5-5","datum":"2026-10-15","urteil":"korrigieren","pruefsumme":"5a8559684541183e"}},{"id":"qx-d2-027","clusterId":"D","werkstueckRef":"D.3.9","stufe":4,"question":"Wie reagierst du am besten?","scenario":"Eine Verwandte fragt zu jeder deiner Aussagen „nur mal nach“, erkennt nie etwas an und erzählt hinterher, du seist gereizt gewesen. Du hast schon drei ihrer Fragen mit Belegen beantwortet. Auf keine Antwort ist sie eingegangen: Sie hat weder zugestimmt noch widersprochen noch etwas an ihrer Sicht geändert, sondern jedes Mal die nächste Frage gestellt.","options":["Weiter jede Frage ausführlich beantworten, weil jede unbeantwortete Frage in der Wahrnehmung der anderen als verlorener Punkt zählt.","Ihre Behauptungen im gleichen Umfang hinterfragen, weil so die Beweislast auf beide Seiten verteilt wird und sie selbst Belege liefern muss.","Aussprechen, dass sie auf keine Antwort eingegangen ist, und das Gespräch beenden, weil ein Austausch ohne Gegenseitigkeit kein echtes Gespräch mehr ist.","Ihr eine feste Zahl von Fragen pro Treffen zugestehen, weil so der Aufwand für beide Seiten gerecht begrenzt bleibt."],"correctIndex":2,"explanation":"Wer eine Behauptung belegt hat, hat seine Pflicht erfüllt. Weitere Belege schuldest du erst, wenn dein Gegenüber mit dem Beleg gearbeitet hat: ihn prüft, ihm widerspricht, zustimmt oder benennt, was ihn noch nicht überzeugt. Hier kommt auf jede Antwort nur die nächste Frage, bei geringem Aufwand für sie und hohem für dich. Das Ziel ist dann nicht Erkenntnis, sondern Erschöpfung, und wer irgendwann die Geduld verliert, steht als der Unfreundliche da. Weiter jede Frage zu beantworten wäre der Denkfehler, jede Frage verdiene eine Antwort und jede offene Frage sei ein verlorener Punkt. Gegenfragen und ein festes Fragenkontingent ändern nichts daran, dass deine Verwandte nicht mit den Belegen arbeitet; die Grenze ziehst du, wenn das ausbleibt. Ein Gespräch zu beenden, das keines ist, ist kein Rückzug, sondern ein begründetes Urteil über den Gesprächsverlauf.","coreRule":"⚡ Du schuldest Belege einmal, nicht endlos.","beleg":"Werkstück D.3.9 (Kontext & Tiefe, „Die Asymmetrie des Aufwands“; Anti-Denkmuster, „Bekämpfter Fehler“, „Der Ringrichter“ und Skript 2; Anwendung & Relevanz, „Familie und Freundeskreis“), Fußnote gl-d-sealioning (Malki 2014; Johnson 2017)","status":"entwurf","kurz":"Wer Belege gegeben hat, hat seine Pflicht erfüllt; weitere schuldest du erst, wenn sie mit ihnen arbeitet. Folgt auf jede Antwort nur die nächste Frage, darfst du das benennen und aufhören, statt jede offene Frage für einen verlorenen Punkt zu halten.","prueffrage":"Wie viel Mühe hat sie jede ihrer Fragen gekostet, und wie viel Mühe hat dich jede deiner Antworten gekostet?","rueckmeldung":[{"option":0,"text":"Jede Frage zu beantworten wirkt höflich, und Schweigen kann tatsächlich wie ein verlorener Punkt aussehen. Doch kein Punktestand entscheidet hier, sondern ob sie mit deinen Belegen arbeitet, und das tut sie nicht: Der Aufwand liegt allein bei dir."},{"option":1,"text":"Gegenfragen wirken fair, denn wer etwas behauptet, schuldet Belege. Am Kern ändern sie aber nichts: Sie arbeitet nicht mit deinen Belegen, und ein Hin und Her aus Fragen macht daraus noch kein Gespräch."},{"option":3,"text":"Ein Kontingent begrenzt den Aufwand und klingt gerecht. Es lässt aber den Kern bestehen: Auch innerhalb der erlaubten Fragen würde sie nicht auf deine Antworten eingehen, und dann ist die Zahl der Fragen weniger entscheidend als die fehlende Gegenseitigkeit."}],"familie":"kraefte-und-ausstieg","fertigkeit":"F3","quellen":[{"typ":"url","kurz":"Johnson, A. (2017): „The Multiple Harms of Sea Lions“, in: Perspectives on Harmful Speech Online, Berkman Klein Center, Harvard","oeffentlich":true,"url":"https://cyber.harvard.edu/sites/cyber.harvard.edu/files/2017-08_harmfulspeech.pdf","seite":"S. 13","abruf":"2026-10-12"}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"d089c26b080f9244"}},{"id":"qx-d2-028","clusterId":"D","werkstueckRef":"D.3.9","stufe":3,"question":"Warum trifft die Antwort der Nutzerin den Kern dieser Äußerung?","scenario":"Unter einem Beitrag über ein neues Impfprogramm schreibt jemand: „Ist es nicht seltsam, dass genau jetzt so viele Menschen krank werden? Ich frage ja nur.“ Eine Quelle oder Zahl nennt die Person nicht. Eine andere Nutzerin antwortet: „Das ist keine Frage, das ist eine Behauptung.“","options":["Die Frage unterstellt einen Zusammenhang von Impfprogramm und Erkrankungen, ohne ihn zu belegen, und das legt die Nutzerin als verdeckte Behauptung offen.","Die Frage schließt aus dem zeitlichen Zusammentreffen auf eine Ursache, und das legt die Nutzerin als Fehlschluss von der bloßen Abfolge auf die Wirkung offen.","Die Frage setzt voraus, dass gerade auffällig viele Menschen krank werden, ohne eine Zahl zu nennen, und das legt die Nutzerin als unbelegte Behauptung offen.","Die Frage enthält mit dem Wort „seltsam“ bereits eine Wertung, und das legt die Nutzerin als Meinung offen, die sich nur als neutrale Frage ausgibt."],"correctIndex":0,"explanation":"Die Äußerung ist grammatisch eine Frage, legt aber eine Behauptung nahe: einen Zusammenhang zwischen dem Impfprogramm und den Erkrankungen. Solche Fragen sind verkleidete Behauptungen („Ist es nicht seltsam, dass …?“): Sie lassen sich streuen, ohne belegt werden zu müssen. Der Fragende kann sich bei Widerspruch darauf zurückziehen, er habe ja nur gefragt. Wer so antwortet, wie die Nutzerin es tut, legt die versteckte Behauptung frei, und erst dann lässt sie sich prüfen: Was genau wird nahegelegt, und wofür gibt es Belege? Ein ehrlicher Fragender arbeitet dagegen mit der Antwort: Er prüft sie, widerspricht ihr oder benennt, was ihn noch nicht überzeugt.","coreRule":"⚡ Prüfe bei jeder Frage, welche Behauptung sie mitführt, und wer diese Behauptung belegen müsste.","beleg":"Werkstück D.3.9 (Kontext & Tiefe, letzter Absatz, letzter Satz „Ein Verwandter ist das ‚Ich stelle doch nur Fragen‘ …“)","status":"entwurf","kurz":"Die Frage legt einen Zusammenhang zwischen Impfprogramm und Erkrankungen nahe, ohne ihn auszusprechen oder zu belegen. Wer sie als Behauptung benennt, macht sichtbar, was sich erst dann prüfen lässt.","prueffrage":"Würde sich an der Wirkung des Beitrags etwas ändern, wenn derselbe Satz ohne Fragezeichen dastünde?","rueckmeldung":[{"option":1,"text":"Von der bloßen Abfolge auf eine Ursache zu schließen, wäre tatsächlich ein typischer Fehler. Die Nutzerin wirft ihn aber nicht vor, sie benennt nur, dass hier etwas behauptet wird. Erst danach lässt sich prüfen, was."},{"option":2,"text":"Daran stimmt: Auch die Vorannahme, gerade seien auffällig viele Menschen krank, bleibt ohne Zahl. Sie ist aber nur der Rahmen. Im Kern wird ein Zusammenhang mit dem Impfprogramm nahegelegt, und der fehlt in dieser Antwort."},{"option":3,"text":"Daran stimmt: „Seltsam“ färbt die Frage wertend ein. Die Nutzerin spricht aber von einer Behauptung, nicht von einer Meinung, und ihr Einwand zielt auf den unbelegten Zusammenhang, den die Frage nahelegt."}],"familie":"beweislast-klaeren","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"Johnson, A. (2017): „The Multiple Harms of Sea Lions“, in: Perspectives on Harmful Speech Online, Berkman Klein Center, Harvard (nur Teilaspekt)","oeffentlich":true,"url":"https://cyber.harvard.edu/sites/cyber.harvard.edu/files/2017-08_harmfulspeech.pdf","seite":"S. 13","abruf":"2026-10-12"}],"thema":"Netz und Medien","pruefung":{"lauf":"quiz-audit-v8","modell":"claude-sonnet-5-5","datum":"2026-10-15","urteil":"korrigieren","pruefsumme":"c4c54d81f8eceab2"}},{"id":"qx-d2-029","clusterId":"D","werkstueckRef":"D.4.1","stufe":1,"question":"Welche Rückfrage prüft die Behauptung am besten?","scenario":"Auf der Webseite einer Praxis steht: „Unsere Behandlung löst Blockaden im Energie-Fluss und bringt die Schwingung Ihres Körpers zurück in die Harmonie. Spüren können das allerdings nur besonders sensitive Menschen; technische Geräte registrieren es nicht.“ Eine Freundin überlegt, dafür 400 Euro auszugeben.","options":["„In welcher Einheit misst du diese Energie, und mit welchem Instrument kann man sie auch ohne besonders sensitive Menschen nachweisen?“","„Welche Ausbildung und Zulassung haben die Behandelnden, und sind sie in einem anerkannten Berufsverband organisiert?“","„Mit welchen Nebenwirkungen ist zu rechnen, und kann man die Behandlung abbrechen und sich das Geld erstatten lassen?“","„Gibt es Erfahrungsberichte anderer Kundinnen, und wie viele haben sich nach der Behandlung tatsächlich besser gefühlt?“"],"correctIndex":0,"explanation":"In der Physik ist Energie eine klar definierte, messbare Größe: Man gibt sie in Joule oder Kilowattstunden an und kann sie mit Instrumenten nachweisen. Hier wird dasselbe Wort zur vagen Allzweck-Erklärung: Es gibt keine Einheit, kein Messgerät, und wahrnehmbar soll es nur für „Sensitive“ sein. Dadurch lässt sich die Behauptung nie widerlegen, denn jeder Misserfolg ließe sich mit mangelnder Sensitivität erklären. Die Frage nach Einheit und Instrument zwingt dazu, den Begriff messbar zu machen oder zuzugeben, dass er nur bildlich gemeint ist. Fragen nach Ausbildung oder Nebenwirkungen sind beim Kauf einer Behandlung vernünftig, klären aber nicht, ob das behauptete Phänomen überhaupt existiert.","coreRule":"⚡ Frag bei „Energie“ und „Schwingung“ nach Einheit und Messgerät.","beleg":"Werkstück D.4.1 (Der kaputte Fernseher; Kontext & Tiefe)","status":"entwurf","kurz":"Das Wort „Energie“ ist in der Physik messbar, hier hat es weder Einheit noch Messgerät. Und weil es nur „Sensitive“ spüren, ließe sich jeder Misserfolg wegerklären. Die Frage nach Einheit und Instrument zwingt zur Klärung.","prueffrage":"Woran könnte man erkennen, dass die Behauptung falsch ist, wenn jeder Misserfolg erklärbar bleibt?","rueckmeldung":[{"option":1,"text":"Nach Ausbildung und Zulassung zu fragen, ist beim Kauf einer Behandlung vernünftig. Ob der behauptete Energie-Fluss überhaupt existiert, klärt sie aber nicht: Auch gut ausgebildete Fachleute können etwas anbieten, das sich nicht prüfen lässt."},{"option":2,"text":"Nebenwirkungen und eine mögliche Erstattung sind vor einer Zahlung von 400 Euro sinnvoll zu klären. Sie sagen jedoch nichts darüber, ob die Blockaden und die Schwingung real sind; selbst bei Rückerstattung bliebe die Behauptung unprüfbar."},{"option":3,"text":"Erfahrungsberichte wirken überzeugend, sind aber Einzelfälle ohne Vergleich mit Menschen ohne Behandlung. Wer sich besser fühlt, kann dafür viele Gründe haben; der behauptete Mechanismus ist damit nicht belegt."}],"familie":"begriff-messbar-machen","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"Memorial Sloan Kettering Cancer Center: „BioResonance Therapy“ (Stand 25.02.2021)","oeffentlich":true,"url":"https://www.mskcc.org/cancer-care/integrative-medicine/herbs/bioresonance-therapy","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Ernst, E. (2023): Vorsicht Heilpraktiker: Eine kritische Analyse. Berlin: Springer, Abschn. 13.4 „Bioresonanz“ (DOI 10.1007/978-3-662-66742-2)","oeffentlich":false}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v8","modell":"claude-sonnet-5-5","datum":"2026-10-15","urteil":"ok","pruefsumme":"074fa5991be556d0"}},{"id":"qx-d2-030","clusterId":"D","werkstueckRef":"D.4.1","stufe":2,"question":"Welche Rückfrage prüft diese Werbeaussage am wirksamsten?","scenario":"Auf einer Website steht: „Unser Kristall sendet starke Heilenergie aus und stellt die richtige Frequenz Ihrer Organe wieder her.“ Eine Messgröße oder Einheit wird nirgends genannt.","options":["„Wie viele Organe sind von dieser Wirkung betroffen, und wie lange hält sie an?“","„In welcher Einheit messen Sie diese Energie, und mit welchem Instrument weisen Sie sie nach?“","„Aus welchem Material besteht der Kristall, und aus welchem Land stammt er ursprünglich?“","„Gibt es eine Rückgabegarantie, falls man die Wirkung nicht bemerkt, und wie lange gilt sie?“"],"correctIndex":1,"explanation":"Der Anbieter borgt sich Begriffe aus der Physik, ohne ihre messbare Bedeutung mitzuliefern. Energie lässt sich in Joule angeben, eine Strahlungsleistung in Watt, eine Frequenz in Hertz, und all das lässt sich mit Instrumenten nachweisen. Die Frage nach Einheit und Messgerät verlangt genau diesen Nachweis und zeigt, ob mehr als eine Metapher dahintersteckt.","coreRule":"⚡ Keine Einheit, kein Messgerät, keine Physik.","beleg":"Werkstück D.4.1 (Kontext & Tiefe, „Die wissenschaftliche Bedeutung“; Red Flags)","status":"entwurf","kurz":"Einheit und Messinstrument zu erfragen verlangt den Nachweis, dass die Energie überhaupt messbar existiert. Wer stattdessen nach Umfang, Dauer oder Rückgabe fragt, übernimmt die Behauptung zunächst als gegeben.","prueffrage":"Welche Antwort könnte der Anbieter auf eine Frage geben, ohne dass sich irgendetwas an ihr überprüfen ließe?","rueckmeldung":[{"option":0,"text":"Organzahl und Wirkdauer sind für Käufer naheliegende Fragen. Sie setzen die Wirkung aber schon voraus und fragen nur nach ihrem Umfang, nicht danach, ob es die behauptete Energie überhaupt gibt."},{"option":2,"text":"Material und Herkunft sind als Kaufinformation nützlich. Sie sagen aber nichts darüber, ob der Kristall Heilenergie aussendet, die Aussage selbst bleibt dadurch ungeprüft."},{"option":3,"text":"Eine Rückgabegarantie schützt vor finanziellem Verlust und ist für Käufer sinnvoll. Ob es die behauptete Energie gibt, klärt sie jedoch nicht, die Behauptung bleibt so unüberprüft stehen."}],"familie":"begriff-messbar-machen","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"Memorial Sloan Kettering Cancer Center: „BioResonance Therapy“ (Stand 25.02.2021)","oeffentlich":true,"url":"https://www.mskcc.org/cancer-care/integrative-medicine/herbs/bioresonance-therapy","abruf":"2026-10-12"},{"typ":"url","kurz":"Ernst, E. (2020): „Bioresonance: a new and hilariously ingenious study“, edzardernst.com, 09.04.2020","oeffentlich":true,"url":"https://edzardernst.com/2020/04/bioresonance-a-new-and-hilariously-ingenious-study/","abruf":"2026-10-12"}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v5","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"60bb3ea61ecda22d"}},{"id":"qx-d2-031","clusterId":"D","werkstueckRef":"D.4.1","stufe":3,"question":"Welche dieser drei Situationen ist problematisch und warum?","options":["Situation 1, weil „Energie“ in der Physik fest definiert ist und die Verwendung des Wortes für ein Raumgefühl Zuhörer deshalb in die Irre führt.","Situation 2, weil ein bildhaftes Wort als messbare Größe ausgegeben wird und daraus Diagnosen und teure Behandlungen folgen.","Situation 3, weil „Vibes“ auf eine Schwingung verweist, die sich ohne Messgerät nicht belegen lässt, sodass die Aussage unseriös wirkt.","Alle drei Situationen, weil in jeder ein Wort aus der Physik für etwas benutzt wird, das niemand gemessen hat und das nur so klingt."],"correctIndex":1,"explanation":"Eine Metapher wie „gute Energie“ oder „gute Vibes“ beschreibt ein Gefühl und erhebt keinen Messanspruch. Sie schadet niemandem, solange alle verstehen, dass sie bildlich gemeint ist. Problematisch wird es, wenn dieselbe Redeweise als buchstäbliche, physikalische Realität auftritt: Dann müsste sich die behauptete „Frequenz“ in einer physikalischen Einheit und mit einem Instrument messen lassen. Hängen daran auch noch medizinische Diagnosen und teure Behandlungen, kann ein falscher Messanspruch echten Schaden anrichten. Entscheidend ist also nicht, ob ein Fachwort außerhalb der Fachsprache auftaucht, sondern ob aus einem Bild ein Messwert gemacht wird, auf den Entscheidungen mit Konsequenzen gebaut werden.","coreRule":"⚡ Eine Metapher ist harmlos, bis sie als Messwert verkauft wird.","beleg":"Werkstück D.4.1 (Der Kipppunkt)","status":"entwurf","scenario":"Drei Situationen:\\n(1) Eine Freundin betritt dein neues Wohnzimmer und sagt: „Der Raum hat eine richtig gute Energie.“\\n(2) Ein Anbieter bewirbt ein Gerät, das die „Schwingungsfrequenz“ deiner Organe misst, und erklärt daraus eine Diagnose samt teurem Behandlungsplan.\\n(3) Ein Kollege sagt nach einem gelungenen Workshop: „Die Vibes waren heute super.“","kurz":"Problematisch ist Situation 2: Dort wird aus einem Bild eine messbare Größe, und auf sie stützen sich Diagnose und teure Behandlung. Ein Physikwort allein ist kein Fehler; „Energie“ und „Vibes“ beschreiben nur ein Gefühl und behaupten keine Messung.","prueffrage":"Was folgt in jeder der drei Situationen auf die Äußerung?","rueckmeldung":[{"option":0,"text":"Es stimmt, dass „Energie“ in der Physik fest definiert ist. Die Freundin behauptet aber keine Messung, sondern beschreibt ein Raumgefühl, und alle verstehen das bildlich. Verwirrend wäre es erst, wenn jemand daraus einen messbaren Wert machte."},{"option":2,"text":"„Vibes“ klingt nach Schwingung, ist hier aber nur ein Wort für die Stimmung im Workshop. Niemand behauptet, etwas gemessen zu haben, also gibt es nichts zu belegen. Bildhafte Rede wirkt nicht schon deshalb unseriös, weil sie ein Fachwort anklingen lässt."},{"option":3,"text":"In allen drei Fällen klingt ein Physikwort an, und gemessen hat wohl niemand etwas. Der Unterschied liegt darin, dass nur eine Situation eine Messung behauptet und darauf Diagnosen und Kosten baut. Ein Fachwort im Alltag ist für sich noch kein Problem."}],"familie":"begriff-messbar-machen","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"Memorial Sloan Kettering Cancer Center: „BioResonance Therapy“ (Stand 25.02.2021)","oeffentlich":true,"url":"https://www.mskcc.org/cancer-care/integrative-medicine/herbs/bioresonance-therapy","abruf":"2026-10-12"}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v5","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"ok","pruefsumme":"152aefb0bd417f36"}},{"id":"qx-d2-032","clusterId":"D","werkstueckRef":"D.4.1","stufe":4,"question":"Ein Anbieter wirbt: „Unser Gerät misst die Frequenzen deiner Organe und deckt Disharmonien auf.“ Du darfst das Gerät aufschrauben und die Messtechnik prüfen. Was findest du bei einem Gerät, dessen Werbeversprechen sich nur als Kundentäuschung erklären lässt?","options":["Eine einfache Schaltung, die die elektrische Leitfähigkeit der Haut misst, ohne irgendetwas über einzelne Organe zu erfassen.","Ein Elektrodenpaar, das die elektrischen Herzströme ableitet und daraus Herzfrequenz und Rhythmus des Herzens berechnet.","Ein Mikrofon samt Auswertung, das Herz- und Atemgeräusche aufnimmt und deren Frequenzen für beide Organe getrennt anzeigt.","Elektroden am Kopf, die die Hirnströme ableiten und deren Frequenzbänder getrennt auswerten und anzeigen."],"correctIndex":0,"explanation":"Hinter dem Wort „Frequenz“ steckt hier keine Organmessung. Bioresonanzgeräte bestehen im Wesentlichen aus einer Schaltung, die die Leitfähigkeit der Haut misst (Ernst 2023), und eine Hautleitfähigkeit sagt nichts über einzelne Organe; „Organfrequenzen“ und „Disharmonien“ sind damit keine Messwerte, sondern Deutung. Die übrigen Funde würden tatsächlich etwas an Herz, Lunge oder Gehirn erfassen und das Versprechen zumindest teilweise einlösen, wären also keine bloße Täuschung, sondern Messtechnik, wie sie auch in der Medizin vorkommt. Die Prüffrage lautet immer: Was misst das Gerät tatsächlich, in welcher Einheit, mit welchem Sensor, und wie wurde geprüft, dass der Messwert zum behaupteten Organ gehört? Ein bloß geliehenes Wort wie „Frequenz“ verleiht dem Gerät nur den Anschein von Wissenschaft.","coreRule":"⚡ Frag, was das Gerät tatsächlich misst, nicht, was der Prospekt behauptet.","beleg":"Werkstück D.4.1 (Anwendung & Relevanz, „In der Pseudomedizin“); Fn. gl-d-bioresonanz (Ernst 2023, Abschn. 13.4, S. 120)","status":"entwurf","scenario":"","kurz":"Eine Schaltung, die nur Hautleitfähigkeit misst, sagt nichts über einzelne Organe aus. „Organfrequenzen“ sind dann keine Messwerte, sondern Deutung. Das Wort „Frequenz“ gibt dem Gerät bloß den Anschein von Wissenschaft.","prueffrage":"Welche Größe zeigt das Gerät an, in welcher Einheit, und wie wurde belegt, dass der Wert zu einem bestimmten Organ gehört?","rueckmeldung":[{"option":1,"text":"Herzströme abzuleiten ist echte Messtechnik, wie sie auch die Medizin nutzt. Ein solcher Fund würde das Versprechen für das Herz zumindest teilweise einlösen und wäre damit keine bloße Täuschung."},{"option":2,"text":"Herz- und Atemgeräusche aufzunehmen erfasst tatsächlich etwas an Herz und Lunge, auch das kennt die Medizin. Das Versprechen wäre damit zumindest teilweise eingelöst, also nicht allein Kundentäuschung."},{"option":3,"text":"Hirnströme mit getrennten Frequenzbändern auszuwerten ist echte, medizinisch etablierte Messtechnik am Gehirn. Das löst das Versprechen zumindest teilweise ein und wäre daher keine reine Täuschung."}],"familie":"begriff-messbar-machen","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"Ernst, E. (2020): „Bioresonance: a new and hilariously ingenious study“, edzardernst.com, 09.04.2020","oeffentlich":true,"url":"https://edzardernst.com/2020/04/bioresonance-a-new-and-hilariously-ingenious-study/","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Ernst, E. (2023): Vorsicht Heilpraktiker: Eine kritische Analyse. Berlin: Springer, Abschn. 13.4 „Bioresonanz“ (DOI 10.1007/978-3-662-66742-2)","oeffentlich":false},{"typ":"url","kurz":"Memorial Sloan Kettering Cancer Center: „BioResonance Therapy“","oeffentlich":true,"url":"https://www.mskcc.org/cancer-care/integrative-medicine/herbs/bioresonance-therapy","abruf":"2026-10-12"}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v4","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"435d344723845fe1"}},{"id":"qx-d2-033","clusterId":"D","werkstueckRef":"D.4.2","stufe":1,"question":"Welche Frage prüft die Behauptung des Verkäufers am besten?","scenario":"Ein Verkäufer preist einen rostigen Kleinwagen an: „Das ist ein Quanten-Auto. Denk mit deinem Quantenbewusstsein an dein Ziel, dann kollabiert die Wahrscheinlichkeitswelle des Motors zu deinen Gunsten.“","options":["Welche von Fachleuten geprüfte Messung zeigt, dass ein Quanteneffekt den Motor dieses Autos beeinflusst?","Welche Belege zeigt der Verkäufer für Wartung und Zustand des Motors, und wann war der Wagen zuletzt beim TÜV?","Was kostet der rostige Kleinwagen, und was kosten vergleichbare Modelle ohne Quantenversprechen auf dem Markt?","Wie lange verkauft der Verkäufer schon Gebrauchtwagen, und wie viele Kunden haben sich bisher beschwert?"],"correctIndex":0,"explanation":"Der Verkäufer benutzt Begriffe aus der Quantenphysik („Wahrscheinlichkeitswelle“, „Kollaps“). Deren Gesetze gelten zwar auch für große Objekte, doch Überlagerungen zerfallen bei einem Auto durch die ständige Wechselwirkung mit der Umgebung so schnell, dass man sie nicht beobachten kann (Dekohärenz); sichtbar werden sie nur an gut abgeschirmten Systemen wie einzelnen Teilchen, Atomen oder Molekülen. Die Quantenbegriffe dienen hier als Wissenschafts-Anstrich: Weil Laien die echte Quantenphysik kaum nachprüfen können, lässt sich ihr Vokabular als Schutzschild gegen Kritik missbrauchen. Wer die Behauptung prüfen will, muss deshalb nach einem Nachweis für den behaupteten Effekt fragen. Fragen nach Wartung und TÜV sind beim Autokauf vernünftig, sagen aber nichts über den Quanteneffekt. Der Preisvergleich klärt, ob der Wagen sein Geld wert ist, nicht ob die Behauptung stimmen kann. Die Erfahrung des Verkäufers und Beschwerden von Kunden sagen etwas über ihn, nicht über seine Behauptung.","coreRule":"⚡ Wenn ein Alltagsding „Quanten“ im Namen trägt, frag nach der Studie, die den Quanteneffekt messbar nachweist.","beleg":"Werkstück D.4.2 (Der erleuchtete Autoverkäufer; Kernidee)","status":"entwurf","kurz":"Wer die Behauptung prüfen will, muss nach einem Nachweis für den behaupteten Effekt fragen. Quantenbegriffe wirken wissenschaftlich, doch bei einem Auto zerfallen Überlagerungen durch die Umgebung so schnell, dass man sie nicht beobachten kann.","prueffrage":"Was müsste am Auto anders ablaufen, wenn du an dein Ziel denkst, als wenn du es nicht tust?","rueckmeldung":[{"option":1,"text":"Wartung und TÜV sind beim Autokauf eine vernünftige Frage und zeigen, in welchem Zustand der Motor wirklich ist. Über den behaupteten Quanteneffekt sagen sie jedoch nichts, den prüfen sie nicht."},{"option":2,"text":"Der Preisvergleich zeigt, ob der Wagen sein Geld wert ist, und das ist beim Kauf wichtig. Ob die Behauptung vom Quanteneffekt stimmen kann, bleibt dabei aber ungeprüft."},{"option":3,"text":"Wie lange der Verkäufer im Geschäft ist und wie viele Kunden sich beschwert haben, sagt etwas über ihn und seinen Ruf. Die Behauptung selbst wird dadurch weder gestützt noch widerlegt."}],"familie":"begriff-messbar-machen","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"Zurek, W. H. (2003): „Decoherence, einselection, and the quantum origins of the classical“, Rev. Mod. Phys. 75, 715 (DOI 10.1103/RevModPhys.75.715), arXiv-Fassung","oeffentlich":true,"url":"https://arxiv.org/abs/quant-ph/0105127","abruf":"2026-10-12"},{"typ":"url","kurz":"Universität Wien, Quantum Science (Arndt-Gruppe): „2.000 Molecules exist at two places at once“, 09.12.2019","oeffentlich":true,"url":"https://quantum.univie.ac.at/news/details-news/news/2000-molecules-exist-at-two-places-at-once/","abruf":"2026-10-12"}],"thema":"Geld und Zahlen","pruefung":{"lauf":"quiz-audit-v4","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"2b7aaeef0053e719"}},{"id":"qx-d2-034","clusterId":"D","werkstueckRef":"D.4.2","stufe":2,"question":"Welche Gegenfrage prüft die Behauptung des Coaches am besten?","scenario":"Ein Coach sagt, durch „Quantenverschränkung“ und die Kraft deiner Absicht könnest du deine Krankheit „zum Kollabieren bringen“. Du willst herausfinden, ob an der Behauptung etwas dran ist.","options":["Welche Stelle hat dich für diese Methode zertifiziert, und wie lange arbeitest du schon in diesem Beruf?","Welche Studie zeigt, dass ein solcher Quanteneffekt im menschlichen Körper messbar wirkt, und wo ist sie erschienen?","Wie genau soll deine Absicht über die Verschränkung auf die Krankheit wirken, und kannst du mir diesen Ablauf erklären?","Welche Erfahrungsberichte früherer Klienten sprechen für deine Methode, und wo kann ich ihre Bewertungen nachlesen?"],"correctIndex":1,"explanation":"Geprüft werden muss die Behauptung, nicht die Person. Quanteneffekte wie Verschränkung oder Überlagerung sind real, lassen sich aber nur an gut abgeschirmten Systemen beobachten. In größeren Systemen zerfallen die Überlagerungen durch die ständige Wechselwirkung mit der Umgebung so schnell, dass man sie nicht beobachten kann (Dekohärenz). Ob so ein Effekt im menschlichen Körper etwas heilt, lässt sich deshalb nur mit einer begutachteten Studie am konkreten System belegen. Für Heilversprechen dieser Art gibt es eine solche Studie nicht. Ein Zertifikat oder Berufsjahre helfen nicht weiter: Eine Quelle, die nur ein spiritueller Guru oder Coach ist, liefert keinen Nachweis am System. Erfahrungsberichte beantworten die Kernfrage nicht, ob ein Quanteneffekt im Körper eine messbare Wirkung hat. Sie liefern keinen Nachweis am konkreten System.","coreRule":"⚡ Verlang den Nachweis am konkreten System, nicht den Titel der Person.","beleg":"Werkstück D.4.2 (Anti-Denkmuster, Aktivierungs-Frage)","status":"entwurf","kurz":"Ob ein Quanteneffekt im Körper etwas heilt, lässt sich nur mit einer begutachteten Studie am konkreten System belegen, denn solche Überlagerungen zerfallen in größeren Systemen sehr schnell. Naheliegend ist, die Person zu prüfen statt ihre Behauptung.","prueffrage":"Woran ließe sich von außen erkennen, ob deine Absicht tatsächlich etwas an der Krankheit verändert hat?","rueckmeldung":[{"option":0,"text":"Nach Qualifikation zu fragen, wirkt im Alltag vernünftig. Hier prüft sie aber den Coach und nicht seine Behauptung: Ein Zertifikat oder viele Berufsjahre sagen nichts darüber, ob ein Quanteneffekt im Körper etwas bewirkt."},{"option":2,"text":"Nach dem Ablauf zu fragen, kann Lücken sichtbar machen. Eine Erklärung bleibt aber eine Behauptung, und mit Fachwörtern lässt sie sich beliebig plausibel ausschmücken. Ein Nachweis am konkreten System ist sie nicht."},{"option":3,"text":"Erfahrungsberichte können Hinweise geben und zeigen, was Klienten erlebt haben. Sie beantworten aber nicht, ob ein Quanteneffekt im Körper messbar wirkt, und lassen offen, ob andere Gründe zur Besserung geführt haben. Das ist kein Nachweis am konkreten System."}],"familie":"autoritaet-pruefen","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Zurek, W. H. (2003): „Decoherence, einselection, and the quantum origins of the classical“, Rev. Mod. Phys. 75, 715, arXiv-Fassung","oeffentlich":true,"url":"https://arxiv.org/abs/quant-ph/0105127","abruf":"2026-10-12"}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v8","modell":"claude-sonnet-5-5","datum":"2026-10-15","urteil":"korrigieren","pruefsumme":"bab679c8470e2041"}},{"id":"qx-d2-035","clusterId":"D","werkstueckRef":"D.4.2","stufe":3,"question":"Ein Esoterik-Coach sagt: „Quantenphysik gilt nur für Atome. Ein Fußball ist nie an zwei Orten gleichzeitig, also ist klar, dass Quantengesetze bei großen Objekten einfach aufhören. Meine Kunden brauchen sich um Quantenphysik im Alltag also keine Sorgen zu machen.“ Du willst ihm nicht nur die falsche Schlussfolgerung nachweisen, sondern auch erklären, warum der Ball sich trotzdem klassisch verhält. Welche Erklärung ist die sparsamste und zugleich sachlich haltbar?","options":["Die Gesetze gelten auch für den Ball, doch ab einer bestimmten Masse lässt ein zusätzliches Naturgesetz die Überlagerung von selbst zusammenbrechen.","Die Gesetze gelten auch für den Ball, doch seine Überlagerung bleibt dauerhaft bestehen und ist nur zu fein, als dass ein Gerät sie messen könnte.","Die Gesetze gelten auch für den Ball, doch die Umgebung lässt seine Überlagerung so schnell zerfallen, dass man sie nicht beobachten kann.","Die Gesetze gelten auch für den Ball, doch sobald jemand hinsieht, beendet dessen Bewusstsein die Überlagerung und legt den Ball auf einen Ort fest."],"correctIndex":2,"explanation":"Die Quantenphysik beschränkt sich nicht auf das Subatomare: Überlagerung wurde schon an Molekülen aus rund 2.000 Atomen nachgewiesen (Fein u. a. 2019). Eine Grenze, an der die Gesetze enden, ist also nicht belegt. Dass der Ball trotzdem klassisch wirkt, erklärt die Dekohärenz: Große Objekte stehen ständig in Wechselwirkung mit ihrer Umgebung, wodurch ihre Überlagerungen so schnell zerfallen, dass man sie nicht beobachten kann. Dieselben Gesetze erzeugen also das klassische Verhalten. Die Erklärung kommt ohne Sonderregel für große Dinge aus und ist deshalb die sparsamste. Das Bewusstsein des Beobachters klingt nach Quantenphysik, ist aber die esoterische Umdeutung des Beobachtereffekts und gilt als Pseudowissenschaft.","coreRule":"⚡ Wenn ein Effekt im Alltag fehlt, schließe nicht auf „Gesetz endet hier“. Frage, welcher Mechanismus ihn unbeobachtbar macht. Bei Quanteneffekten zerstört die Umgebung die Überlagerung großer Objekte so schnell, dass sie unbeobachtbar bleibt.","beleg":"Werkstück D.4.2 (Kontext & Tiefe, „Die wissenschaftliche Bedeutung“); Fn. gl-d-quanten (Fein u. a. 2019, Nature Physics 15), gl-d-dekohaerenz (Zurek 2003, Reviews of Modern Physics 75, S. 715–775)","status":"entwurf","scenario":"","kurz":"Der Ball folgt denselben Gesetzen wie Atome. Weil er ständig mit seiner Umgebung wechselwirkt, zerfällt jede Überlagerung blitzschnell, daher wirkt er klassisch. Aus „nie an zwei Orten“ folgt kein Ende der Gesetze, und eine Sonderregel braucht es nicht.","prueffrage":"Wurde Überlagerung schon an Objekten nachgewiesen, die deutlich größer sind als einzelne Atome?","rueckmeldung":[{"option":0,"text":"Eine Massengrenze klingt klar und übersichtlich, und solche Kollapsmodelle werden tatsächlich diskutiert. Belegt sind sie aber nicht, und sie sind gar nicht nötig, weil die Umgebung das klassische Verhalten schon ohne Zusatzgesetz erklärt."},{"option":1,"text":"Dass sich Überlagerungen bei großen Objekten kaum messen lassen, stimmt, und das klingt nach bloßer Messgenauigkeit. Der Grund ist aber ein anderer: Die Überlagerung bleibt nicht bestehen, ihre Information fließt in die Umgebung ab."},{"option":3,"text":"Das Wort „Beobachter“ legt nahe, dass es auf das Hinsehen und das Bewusstsein ankommt. Entscheidend ist aber die Wechselwirkung mit der Umgebung, die auch ohne Menschen stattfindet. Das Bewusstsein als Auslöser ist eine esoterische Umdeutung."}],"familie":"mechanismus-verlangen","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"Universität Wien, Quantum Science (Arndt-Gruppe): „2.000 Molecules exist at two places at once“, 09.12.2019 (zu Fein u. a. 2019)","oeffentlich":true,"url":"https://quantum.univie.ac.at/news/details-news/news/2000-molecules-exist-at-two-places-at-once/","abruf":"2026-10-12"},{"typ":"doi","kurz":"Fein, Y. Y. u. a. (2019): „Quantum superposition of molecules beyond 25 kDa“, Nature Physics 15, 1242–1245","oeffentlich":false,"doi":"10.1038/s41567-019-0663-9"},{"typ":"url","kurz":"Zurek, W. H. (2003): „Decoherence, einselection, and the quantum origins of the classical“, Rev. Mod. Phys. 75, 715, arXiv-Fassung","oeffentlich":true,"url":"https://arxiv.org/abs/quant-ph/0105127","abruf":"2026-10-12"}],"thema":"Natur und Klima","pruefung":{"lauf":"quiz-audit-v5","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"ok","pruefsumme":"3c6d49f7407c2ff7"}},{"id":"qx-d2-036","clusterId":"D","werkstueckRef":"D.4.2","stufe":4,"question":"Was ist an diesem Schluss fehlerhaft?","scenario":"Eine Anbieterin von „Quantenheilung“ sagt: „Quantenphysik versteht kaum jemand richtig, du nicht und ich auch nicht ganz. Also kannst du nicht ausschließen, dass meine Deutung stimmt. Es könnte also wirken.“","options":["Aus dem Umstand, dass niemand ihre Deutung sicher ausschließen kann, wird gefolgert, sie sei plausibel; Nichtwissen gilt hier als Beleg.","Sie spricht dir das Verständnis der Quantenphysik ab, damit deine Zweifel nicht zählen; sie wehrt die Kritik über deine Person ab.","Ihre Ausgangslage ist überzogen; Quantenphysik ist gut erforscht, und der Fehler liegt darin, dass sie dieses Fachwissen kleinredet.","Viel ist daran nicht fehlerhaft; wenn Quantenphysik kaum jemand richtig versteht, ist Offenheit für ihre Deutung die ehrlichere Haltung."],"correctIndex":0,"explanation":"Der Schluss lautet: „Wir verstehen es nicht, also könnte meine Deutung wahr sein.“ Das ist ein Argument aus Unwissenheit. Aus Nichtwissen wird hier Plausibilität gemacht, obwohl Nichtwissen kein Beleg ist. Die Komplexität des Themas wird als Schutzschild gegen Kritik missbraucht. Wirkt etwas, muss sich das belegen lassen, etwa durch eine Studie, die an einem biologischen System eine messbare Wirkung zeigt. Die Schwierigkeit des Themas ersetzt diesen Beleg nicht. Zudem lassen sich Quanteneffekte nur an gut abgeschirmten, kleinen Systemen beobachten, weil die Umgebung Überlagerungen großer Objekte sehr schnell zerstört (Dekohärenz).","coreRule":"⚡ „Das kann man nicht widerlegen“ ist kein Beleg.","beleg":"Werkstück D.4.2 (Kontext & Tiefe, „Die pseudowissenschaftliche Umdeutung“; Verweis auf Werkstück B.11, Argument aus Unwissenheit)","status":"entwurf","kurz":"Aus „Das versteht kaum jemand“ folgt nicht, dass die Deutung plausibel ist. Wer Nichtwissen als Beleg nimmt, schützt eine Behauptung mit der Schwierigkeit des Themas, statt eine Wirkung nachzuweisen.","prueffrage":"Was ließe sich mit dem Satz „du kannst es nicht ausschließen“ sonst noch alles begründen?","rueckmeldung":[{"option":1,"text":"Das „du nicht“ klingt nach Herabsetzung. Sie schließt sich aber selbst ein („ich auch nicht ganz“) und wehrt keine Person ab. Fehlerhaft ist der Schluss vom allgemeinen Nichtverstehen auf die Möglichkeit ihrer Deutung."},{"option":2,"text":"Daran stimmt: Quantenphysik ist gut erforscht und experimentell sehr genau geprüft. Doch selbst wenn sie völlig unverstanden wäre, bliebe der Schluss fehlerhaft, denn Nichtwissen macht eine Deutung nicht plausibel."},{"option":3,"text":"Offenheit klingt redlich, und ausschließen kann man vieles nicht. Aus „nicht ausschließbar“ folgt aber nicht „könnte wirken“. Eine Wirkung muss sich belegen lassen, etwa durch eine Studie mit messbarem Effekt."}],"familie":"widerlegung-benennen","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"Internet Encyclopedia of Philosophy: „Fallacies“ (Eintrag „Appeal to Ignorance“)","oeffentlich":true,"url":"https://iep.utm.edu/fallacy/","abruf":"2026-10-12"},{"typ":"url","kurz":"Zurek, W. H. (2003): „Decoherence, einselection, and the quantum origins of the classical“, Rev. Mod. Phys. 75, 715, arXiv-Fassung","oeffentlich":true,"url":"https://arxiv.org/abs/quant-ph/0105127","abruf":"2026-10-12"}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v8","modell":"claude-sonnet-5-5","datum":"2026-10-15","urteil":"korrigieren","pruefsumme":"58abb5ac1a749c3d"}},{"id":"qx-d2-037","clusterId":"D","werkstueckRef":"D.4.3","stufe":1,"question":"Ein Händler sagt: „Unser Vitamin C ist rein natürlich, aus handgepflückten Kirschen, und deshalb besser für den Körper als die Tablette aus dem Labor.“ Beide Produkte enthalten dasselbe Molekül. Welche Erwiderung prüft die Behauptung am besten?","scenario":"Du stehst im Reformhaus. Der Händler zeigt dir zwei gleich aussehende Pillen: Pille A mit „natürlichem“ Vitamin C aus Acerolakirschen für den doppelten Preis, Pille B mit synthetischer Ascorbinsäure aus dem Labor. Auf beiden Packungen steht als Wirkstoff dasselbe Molekül, C₆H₈O₆.","options":["Auf das gleiche Molekül C₆H₈O₆ verweisen: Der Körper kann beide nicht unterscheiden, eine bessere Wirkung müsste der Händler mit Studien zur Aufnahme belegen.","Beim Händler klären, ob die Kirschen von Hand gepflückt wurden: Stimmt das, spricht es für eine bessere Wirkung, und die Behauptung des Händlers wäre gestützt.","Die Milligramm Vitamin C beider Packungen vergleichen: Enthält Pille A mehr, wirkt sie stärker, und die Behauptung des Händlers wäre damit bestätigt.","Klären, ob „natürlich“ für Pille A rechtlich geschützt ist: Trifft das zu, wäre damit belegt, dass sie dem Körper besser bekommt."],"correctIndex":0,"explanation":"Der Händler schließt von der Herkunft („natürlich“) auf die Wirkung. Das ist ein Appell an die Natur. Ein Molekül ist durch seine Struktur bestimmt, nicht durch seinen Ursprung: Der Körper kann zwei identische Moleküle nicht unterscheiden. Eine bessere Wirkung müsste der Händler belegen, nicht behaupten. Das ist auch empirisch geprüft: Eine randomisierte Studie (Carr u. a. 2013) fand zwischen Vitamin C aus Kiwis und aus Tabletten keinen Unterschied in der Aufnahme. Was bleibt, ist der Preisaufschlag für ein Wort.","coreRule":"⚡ Gleiche Struktur, gleiche Wirkung: Die Herkunft eines Moleküls ist kein Qualitätsmerkmal; wer eine Überlegenheit behauptet, muss sie belegen.","beleg":"Werkstück D.4.3 (Der Vitamin-C-Test; Kontext & Tiefe); Fn. gl-d-vitc (Carr u. a. 2013, Nutrients 5(9), 3684–3695)","status":"entwurf","kurz":"Der Händler schließt von der Herkunft auf die Wirkung, doch ein Molekül ist durch seine Struktur bestimmt, nicht durch seinen Ursprung. Der Körper kann identische Moleküle nicht unterscheiden; eine bessere Wirkung müsste der Händler belegen.","prueffrage":"Was unterscheidet die beiden Pillen außer Herkunft und Preis?","rueckmeldung":[{"option":1,"text":"Handgepflückt klingt nach Sorgfalt und Qualität. Das betrifft aber die Ernte und sagt nichts darüber, wie das fertige Molekül im Körper wirkt; auch eine zutreffende Auskunft würde die Behauptung nicht stützen."},{"option":2,"text":"Ein Mengenvergleich wirkt sachlich und prüfbar. Er misst aber nur, wie viel enthalten ist, nicht ob die Herkunft etwas ändert. Mehr Milligramm wären ein anderer Vorteil als der behauptete."},{"option":3,"text":"Ein geschützter Begriff wirkt wie ein Gütesiegel. Er regelt aber, wie ein Produkt heißen darf, und nicht, wie es im Körper wirkt. Aus der Bezeichnung folgt daher nichts über die Wirkung."}],"familie":"natuerlich-kein-guetesiegel","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Carr, A. C. u. a. (2013): „A Randomized Steady-State Bioavailability Study of Synthetic versus Natural (Kiwifruit-Derived) Vitamin C“, Nutrients 5(9), 3684–3695 (DOI 10.3390/nu5093684)","oeffentlich":true,"url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC3798928/","abruf":"2026-10-12"}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v5","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"2d913cecb66a8e2f"}},{"id":"qx-d2-038","clusterId":"D","werkstueckRef":"D.4.3","stufe":2,"question":"Was ist an diesem Werbeversprechen im Kern fehlerhaft?","scenario":"Auf einem Shampoo steht: „Frei von Chemie – rein natürlich.“ Ein Kollege sagt: „Dann ist es bestimmt sanfter und sicherer als die Konkurrenz.“","options":["Es setzt „Chemie“ mit „schädlich“ gleich und schließt von „natürlich“ auf Sicherheit, obwohl alle Stoffe Chemie sind und die Herkunft nichts über Sicherheit sagt.","Es formuliert nur ungenau: Gemeint ist „ohne synthetische Zusatzstoffe“, und der Kollege liest daraus zu Recht, dass das Shampoo die Haut eher schont.","Es selbst sagt nichts über Sicherheit: Erst der Kollege macht aus dem Slogan einen Vergleich mit der Konkurrenz, der Fehler liegt in seiner Folgerung.","Es lässt sich nicht nachprüfen: Ob ein Shampoo „rein natürlich“ ist, kann man im Laden nicht kontrollieren, deshalb bleibt die Aussage ein Versprechen."],"correctIndex":0,"explanation":"Alles ist Chemie: Ein Apfel ist ein Beutel voller Chemikalien, und auch Wasser (H₂O) ist Chemie. „Chemiefrei“ ist deshalb ein unmöglicher Zustand und als Eigenschaft eines Produkts bedeutungslos. Der Slogan arbeitet mit der Intuition, Natur sei gütig und das Labor kalt, und überspringt dabei die eigentlich entscheidenden Fragen: Welcher Stoff ist enthalten, in welcher Dosis, und was zeigen kontrollierte Studien zu Wirkung und Verträglichkeit? Die Herkunft eines Moleküls sagt darüber nichts. Ein identisches Molekül wirkt gleich, egal ob es aus einer Pflanze oder aus dem Labor stammt (bei Vitamin C aus Kiwis und aus Tabletten fand eine randomisierte Studie keinen Unterschied in der Aufnahme). Viele der giftigsten Substanzen der Welt sind „rein natürlich“, und synthetische Versionen sind oft reiner und genauer dosierbar. Die Werbung erzeugt also eine Präferenz, noch bevor ein einziges Faktum zur Sicherheit genannt wurde.","coreRule":"⚡ „Chemiefrei“ gibt es nicht: Frag nach Stoff, Dosis und Studie – nicht nach der Herkunft.","beleg":"Werkstück D.4.3 (Kontext & Tiefe, „Alles ist chemisch“; Anwendung & Relevanz, Lebensmittel- und Kosmetikindustrie; Red Flags; Anti-Denkmuster)","status":"entwurf","kurz":"Alles besteht aus Chemie, auch Wasser und Äpfel, deshalb ist „chemiefrei“ ein unmöglicher Zustand. Der Fehler: „Natürlich“ klingt nach „sicher“, doch die Herkunft eines Stoffes sagt nichts über Dosis und Verträglichkeit.","prueffrage":"Was erfährst du aus „Frei von Chemie – rein natürlich“ über die Inhaltsstoffe des Shampoos?","rueckmeldung":[{"option":1,"text":"Dass „ohne Synthetisches“ gemeint sein könnte, ist gut möglich. Der Schluss auf Hautschonung bleibt trotzdem unbelegt, denn auch natürliche Stoffe reizen oder sind giftig. Der Fehler liegt nicht nur in der Wortwahl, sondern im Schluss selbst."},{"option":2,"text":"Dass der Slogan Sicherheit und Konkurrenz nicht ausdrücklich nennt, stimmt. Er legt die Deutung aber nahe: Mit „frei von Chemie“ und „rein natürlich“ weckt er eine Vorliebe, noch bevor ein Faktum genannt wird. Der Fehler steckt schon im Versprechen."},{"option":3,"text":"Schwer kontrollieren lässt sich die Herkunft der Inhaltsstoffe tatsächlich. Selbst eine lückenlose Prüfung würde das Problem aber nicht lösen: „Chemiefrei“ bliebe unmöglich, und „natürlich“ sagte weiterhin nichts über Sicherheit."}],"familie":"natuerlich-kein-guetesiegel","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Carr, A. C. u. a. (2013): „A Randomized Steady-State Bioavailability Study of Synthetic versus Natural (Kiwifruit-Derived) Vitamin C“, Nutrients 5(9), 3684–3695 (DOI 10.3390/nu5093684)","oeffentlich":true,"url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC3798928/","abruf":"2026-10-12"}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v8","modell":"claude-sonnet-5-5","datum":"2026-10-15","urteil":"korrigieren","pruefsumme":"77ea04d4ff57edd0"}},{"id":"qx-d2-039","clusterId":"D","werkstueckRef":"D.4.3","stufe":3,"question":"Wo kippt eine harmlose Vorliebe für „Natürliches“ in eine echte Gefahr?","options":["Eine Person kauft bewusst weniger verarbeitete Lebensmittel, weil sie ihr besser schmecken und weil sie Zutatenlisten mit vielen Zusatzstoffen meidet.","Eine Person lehnt ein ärztlich empfohlenes, gut untersuchtes Medikament ab, weil es im Labor hergestellt wurde und „unnatürlich“ sei, und setzt stattdessen auf einen Kräutertee.","Eine Person greift zu einer Hautcreme mit Pflanzenextrakten, weil sie die Verpackung ansprechender findet als die der Konkurrenz.","Eine Person nimmt zusätzlich zur ärztlich verordneten Behandlung ein pflanzliches Mittel, weil sie sich damit besser fühlt und ihr Arzt davon weiß."],"correctIndex":1,"explanation":"Eine Vorliebe für weniger Verarbeitetes oder Pflanzliches bleibt harmlos, solange sie eine Geschmacks- oder Stilfrage ist. Gefährlich wird sie, wenn die Herkunft zum Maßstab wird und ein wirksames, gut geprüftes Mittel nur deshalb verworfen wird, weil es synthetisch ist. Ob ein Wirkstoff hilft oder schadet, hängt von Struktur, Dosis und belegter Wirkung ab, nicht davon, ob er im Labor oder in einer Pflanze entstand. Vitamin C aus Kiwis und aus Tabletten wird gleich gut aufgenommen. Wer aus „Natürlichkeit“ auf Sicherheit und aus „Labor“ auf Gefahr schließt, gibt im Ernstfall den Nutzen eines Medikaments, eines Impfstoffs oder eines lebensrettenden Zusatzstoffs auf. In den übrigen Fällen geht es um Geschmack, Verpackung oder eine Ergänzung in Absprache mit dem Arzt. Dort wird keine wirksame Behandlung verworfen.","coreRule":"⚡ Eine Vorliebe für Natürliches ist erlaubt; sie wird gefährlich, wenn sie wirksame Mittel verwirft.","beleg":"Werkstück D.4.3 (Der Kipppunkt)","status":"entwurf","scenario":"Vier Leute erzählen, wie sie es mit „natürlich“ und „synthetisch“ halten.","quote":"","quoteLabel":"","kurz":"Gefährlich wird die Vorliebe, wenn die Herkunft zum Maßstab wird und ein gut geprüftes Medikament nur abgelehnt wird, weil es synthetisch ist. Ob ein Stoff hilft oder schadet, hängt von Wirkstoff und Dosis ab, nicht davon, ob er aus Labor oder Pflanze stammt.","prueffrage":"Was steht für jede Person auf dem Spiel, falls sich ihre Wahl als falsch erweist?","rueckmeldung":[{"option":0,"text":"Weniger Verarbeitetes zu bevorzugen und Zutatenlisten mit vielen Zusatzstoffen zu meiden, ist eine Geschmacks- und Stilfrage. Dabei wird keine wirksame Behandlung aufgegeben und auf keine nötige Hilfe verzichtet."},{"option":2,"text":"Eine Creme wegen der Verpackung zu wählen, ist eine reine Geschmacksentscheidung ohne Urteil über Gesundheit. Es wird nichts abgelehnt, was helfen könnte; die Herkunft ist hier nicht der Maßstab."},{"option":3,"text":"Ein pflanzliches Mittel neben einer Therapie wirkt riskant, und Wechselwirkungen kommen tatsächlich vor. Hier läuft die verordnete Behandlung aber weiter, und der Arzt weiß davon. Verworfen wird keine wirksame Therapie."}],"familie":"ergaenzen-oder-ersetzen","fertigkeit":"F4","quellen":[{"typ":"url","kurz":"Carr, A. C. u. a. (2013): „A Randomized Steady-State Bioavailability Study of Synthetic versus Natural (Kiwifruit-Derived) Vitamin C“, Nutrients 5(9), 3684–3695 (DOI 10.3390/nu5093684)","oeffentlich":true,"url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC3798928/","abruf":"2026-10-12"}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"22288620dc3acd5e"}},{"id":"qx-d2-040","clusterId":"D","werkstueckRef":"D.4.3","stufe":4,"question":"Welche Erklärung für die Streifen vom Donnerstag ist die sparsamste und lässt sich zugleich am besten prüfen?","scenario":"In einem Video heißt es, Flugzeuge versprühten „Chemtrails“: Lang stehende weiße Streifen am Himmel seien künstliche Gifte. Dein Nachbar hat notiert: Am Dienstag lösten sich die Streifen nach wenigen Sekunden auf, am Donnerstag blieben sie stundenlang stehen und breiteten sich aus. Laut Wetterdaten war die Luft in Reiseflughöhe am Dienstag trocken, am Donnerstag sehr feucht und kalt.","options":["Die Abgase verteilten sich am Donnerstag in der kalten Luft langsamer und blieben als Dunst stehen; prüfen lässt sich das an weiteren Tagen mit ähnlich kalter Luft.","Die Flugzeuge versprühten am Donnerstag einen Stoff, der sich in feuchter Luft länger hält; prüfen lässt sich das mit Luftproben in Flughöhe an solchen Tagen.","Solche Streifen stehen mal kürzer und mal länger, ohne dass es dafür eines besonderen Grundes bedarf; prüfen lässt sich das, wenn der Nachbar weiter notiert.","Eiskristalle aus dem Wasserdampf der Abgase hielten sich am Donnerstag in der feuchten Kaltluft; prüfen lässt sich das an weiteren Tagen mit bekannter Feuchte."],"correctIndex":3,"explanation":"Die sparsamste Erklärung kommt mit bekannten Vorgängen aus: Die Streifen sind gewöhnliche Kondensstreifen, also Eiskristalle aus dem Wasserdampf der Triebwerksabgase. Wie lange sie stehen bleiben und ob sie sich ausbreiten, hängt von Feuchte und Temperatur der Luft in Flughöhe ab: In sehr feuchter, kalter Luft halten sie sich lange, in trockener verschwinden sie rasch. Genau das zeigen die Notizen des Nachbarn: rasches Verschwinden am trockenen Dienstag, langes Stehen am feuchten, kalten Donnerstag. Diese Erklärung macht eine Vorhersage, die jeder an weiteren Tagen überprüfen kann. „Künstlich“ ist kein Beweis für „giftig“: Wer ein Gift behauptet, muss Stoff, Menge und Beleg nennen.","coreRule":"⚡ „Künstlich“ ist kein Beweis für „giftig“: Frage nach Stoff, Menge und Beleg, nicht nach der Herkunft.","beleg":"Werkstück D.4.3 (Anwendung & Relevanz, „Bei Verschwörungsmythen (Chemtrails etc.)“)","status":"entwurf","kurz":"Der Donnerstag lässt sich mit gewöhnlichen Kondensstreifen erklären: Eiskristalle aus dem Abgas-Wasserdampf halten sich in feuchter, kalter Luft lange. Ein unbekannter Giftstoff ist dafür nicht nötig, nur weil die Streifen künstlich entstehen.","prueffrage":"Was unterscheidet die beiden Tage außer dem Aussehen der Streifen, und könnte schon das den Unterschied erklären?","rueckmeldung":[{"option":0,"text":"Dass die kalte Luft eine Rolle spielt, stimmt, und auch die Prüfung an weiteren Tagen ist sinnvoll. Die Streifen sind aber kein stehen gebliebener Dunst, sondern Eiskristalle, und Kälte allein genügt nicht: Am Dienstag fehlte die Feuchte."},{"option":1,"text":"Ein Stoff, der sich in feuchter Luft hält, erklärt die Beobachtung scheinbar. Er führt aber etwas Unbelegtes ein, obwohl Kondensstreifen aus Abgas-Wasserdampf mit Feuchte und Kälte schon alles erklären. Die Beweislast liegt bei dem, der einen Stoff behauptet."},{"option":2,"text":"Dass die Streifen unterschiedlich lange stehen, stimmt. Es geschieht aber nicht ohne Grund: Am Dienstag war die Luft trocken, am Donnerstag feucht und kalt. „Es schwankt eben“ erklärt nichts und lässt sich nicht prüfen."}],"familie":"natuerlich-kein-guetesiegel","fertigkeit":"F2","quellen":[{"typ":"doi","kurz":"Shearer, C.; West, M.; Caldeira, K.; Davis, S. J. (2016): „Quantifying expert consensus against the existence of a secret, large-scale atmospheric spraying program“, Environ. Res. Lett. 11, 084011","oeffentlich":true,"doi":"10.1088/1748-9326/11/8/084011","abruf":"2026-10-12"},{"typ":"doi","kurz":"Schumann, U. (1996): „On conditions for contrail formation from aircraft exhausts“, Meteorologische Zeitschrift 5(1), 4–23","oeffentlich":true,"doi":"10.1127/metz/5/1996/4","abruf":"2026-10-12"}],"thema":"Natur und Klima","pruefung":{"lauf":"quiz-audit-v8","modell":"claude-sonnet-5-5","datum":"2026-10-15","urteil":"korrigieren","pruefsumme":"9b5f819ffba89392"}},{"id":"qx-d2-041","clusterId":"D","werkstueckRef":"D.4.4","stufe":1,"question":"Wie lässt sich der Unterschied zwischen den beiden Ansätzen am besten beschreiben, obwohl beide „ganzheitlich“ sagen?","scenario":"Du hast chronische Kopfschmerzen. Arzt A untersucht dich gründlich, verschreibt ein Medikament und fragt auch nach Stress, Schlaf und Ernährung. Arzt B untersucht dich nicht körperlich, spricht von einer „Blockade im Energie-Meridian“ und verkauft dir Kristalle. Beide nennen ihren Ansatz „ganzheitlich“.","options":["Arzt A erweitert die überprüfbare Medizin um Lebensstil und Psyche; Arzt B ersetzt sie durch Konzepte, die sich nicht messen lassen.","Arzt A untersucht gründlicher als Arzt B; der Unterschied liegt in der Sorgfalt der Untersuchung, nicht im ganzheitlichen Ansatz selbst.","Arzt A arbeitet schulmedizinisch, Arzt B alternativ; welcher Ansatz ganzheitlicher ist, hängt vor allem vom Weltbild der Patienten ab.","Beide arbeiten ganzheitlich mit anderem Schwerpunkt; Arzt A setzt auf Lebensstil und Medikament, Arzt B auf Energiefluss und Kristalle."],"correctIndex":0,"explanation":"Dass Körper, Geist und Umwelt zusammenhängen, ist unstrittig und in der Medizin etabliert: Die Psychoneuroimmunologie erforscht zum Beispiel, wie Stress das Immunsystem beeinflusst. Arzt A nutzt diesen Gedanken, um eine geprüfte Behandlung zu ergänzen. Arzt B nutzt dieselbe unstrittige Aussage als Eintrittskarte für Diagnosen und Behandlungen, die sich nicht überprüfen lassen. Dass das Wort gleich klingt, sagt nichts darüber, was damit verkauft wird: Wer dem Grundsatz „Körper und Geist sind verbunden“ zustimmt, hat damit noch nicht Kristalle oder Meridian-Blockaden als wirksam anerkannt.","coreRule":"⚡ „Ganzheitlich“ kann ergänzen oder ersetzen: Prüf, was damit verkauft wird.","beleg":"Werkstück D.4.4 (Die zwei Ärzte; Kontext & Tiefe; Anwendung & Relevanz)","status":"entwurf","kurz":"Arzt A erweitert eine geprüfte Behandlung um Stress, Schlaf und Ernährung, Arzt B nutzt dasselbe Wort für Konzepte, die sich nicht überprüfen lassen. Der Fehler wäre, vom gleichen Wort auf gleichwertige Ansätze zu schließen.","prueffrage":"Was hat jeder der beiden Ärzte getan, bevor er seine Behandlung festgelegt hat?","rueckmeldung":[{"option":1,"text":"Arzt A untersucht tatsächlich gründlicher, das fällt sofort auf. Der Unterschied reicht aber tiefer: Es geht nicht um das Maß an Sorgfalt, sondern darum, ob das, was jeweils „ganzheitlich“ heißt, überhaupt überprüfbar ist."},{"option":2,"text":"Die Etiketten „schulmedizinisch“ und „alternativ“ wirken wie eine Erklärung, ordnen aber nur ein. Ob ein Ansatz trägt, hängt nicht vom Weltbild der Patienten ab, sondern davon, ob sich seine Annahmen und Wirkungen prüfen lassen."},{"option":3,"text":"Beide berufen sich auf Ganzheitlichkeit, und ihre Schwerpunkte unterscheiden sich tatsächlich. Gleichwertig sind die Ansätze deshalb nicht: Lebensstil und Medikament lassen sich prüfen, Energiefluss und Kristalle nicht. Dass beide „ganzheitlich“ sagen, macht sie nicht vergleichbar."}],"familie":"ergaenzen-oder-ersetzen","fertigkeit":"F4","quellen":[{"typ":"url","kurz":"Segerstrom, S. C.; Miller, G. E. (2004): „Psychological Stress and the Human Immune System: A Meta-Analytic Study of 30 Years of Inquiry“, Psychological Bulletin 130(4), 601–630","oeffentlich":true,"url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC1361287/","abruf":"2026-10-12"}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v8","modell":"claude-sonnet-5-5","datum":"2026-10-15","urteil":"ok","pruefsumme":"50df3de1c91ec66d"}},{"id":"qx-d2-042","clusterId":"D","werkstueckRef":"D.4.4","stufe":2,"question":"Was ist an dieser Abfolge von Aussage und Schlussfolgerung fehlerhaft?","scenario":"Auf einer Website steht: „Wir betrachten den ganzen Menschen, denn Körper und Geist sind untrennbar verbunden. Deshalb gleichen wir mit unserer Aura-Reinigung Ihre Energiefelder aus.“","options":["Die erste Aussage ist unstrittig; weil ihr niemand widerspricht, wird die darauf gestützte, unbelegte Methode stillschweigend als akzeptiert behandelt.","Die erste Aussage ist schon fragwürdig; „untrennbar verbunden“ ist übertrieben, und auf einer solchen Übertreibung kann die Aura-Reinigung nicht aufbauen.","Die erste Aussage ist in Ordnung; der Fehler liegt eher darin, dass „Aura“ und „Energiefelder“ nirgends erklärt werden und deshalb vage bleiben.","Die erste Aussage ist zutreffend; wenn Körper und Geist verbunden sind, ist es folgerichtig, auch die Energiefelder mitzubehandeln, der Schluss trägt."],"correctIndex":0,"explanation":"Der Text beginnt mit einer Binsenweisheit: Körper und Geist hängen zusammen, das ist auch wissenschaftlich anerkannt. Das „Deshalb“ tut so, als folge die Wirksamkeit der Aura-Reinigung zwangsläufig daraus. Das tut sie nicht. Dass alles verbunden ist, sagt nichts darüber, ob ein bestimmtes Verfahren eine messbare Wirkung hat. Das ist der Motte-and-Bailey-Trick: Die unstrittige „Motte“ (Körper und Geist sind verbunden) dient als Brücke zur umstrittenen „Bailey“ (meine Methode wirkt). Er arbeitet allein mit der unstrittigen Vorbehauptung und dem „Deshalb“. Eine gute Prüffrage lautet: Welchen konkreten, überprüfbaren Beleg gibt es für die Methode selbst, über den bloßen Placebo-Effekt hinaus?","coreRule":"⚡ Trenne die wahre Aussage von der Methode, die dahinter verkauft wird.","beleg":"Werkstück D.4.4 (Kontext & Tiefe, Motte-and-Bailey; Anti-Denkmuster; Werkbank-Frage)","status":"entwurf","kurz":"Dass Körper und Geist zusammenhängen, ist anerkannt und sagt nichts über diese Methode. Der Text nutzt die unstrittige Aussage als Brücke zur umstrittenen und lässt sie dadurch als zwingende Folge erscheinen. Die Wirkung bleibt unbelegt.","prueffrage":"Welche andere Behandlung ließe sich mit dem ersten Satz der Website genauso gut begründen?","rueckmeldung":[{"option":1,"text":"Dass Körper und Geist zusammenhängen, ist wissenschaftlich anerkannt und keine Übertreibung. Der Fehler liegt woanders: Das „Deshalb“ tut so, als folge daraus schon die Wirkung der Methode."},{"option":2,"text":"Unklare Begriffe sind tatsächlich ein Mangel. Aber selbst mit sauber definierten Begriffen bliebe offen, ob die Methode wirkt, denn aus der ersten Aussage folgt das nicht."},{"option":3,"text":"Die erste Aussage stimmt. Doch daraus folgt nicht, dass jedes Verfahren, das sich darauf beruft, auch wirkt. Das „Deshalb“ überbrückt eine Lücke, die ein eigener Beleg für die Methode füllen müsste."}],"familie":"rueckzug-auf-harmloses","fertigkeit":"F2","quellen":[{"typ":"literatur","kurz":"Shackel, N. (2005): „The Vacuity of Postmodernist Methodology“, Metaphilosophy 36(3), 295–320 (DOI 10.1111/j.1467-9973.2005.00370.x)","oeffentlich":false},{"typ":"url","kurz":"Segerstrom, S. C.; Miller, G. E. (2004): „Psychological Stress and the Human Immune System“, Psychological Bulletin 130(4), 601–630","oeffentlich":true,"url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC1361287/","abruf":"2026-10-12"}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v8","modell":"claude-sonnet-5-5","datum":"2026-10-15","urteil":"korrigieren","pruefsumme":"5f838d27e64e2215"}},{"id":"qx-d2-043","clusterId":"D","werkstueckRef":"D.4.4","stufe":3,"question":"Eine Bekannte erzählt dir: „Ich lasse mich jetzt nur noch ‚ganzheitlich‘ behandeln. Meine Heilerin sagt, mein Knoten in der Brust ist eine Energieblockade und braucht keine Untersuchung.“ Woran wird hier das Problem am klarsten sichtbar?","options":["Die Heilerin erklärt den Knoten mit einer „Energieblockade“, einem Begriff, der sich nicht messen lässt, sodass ihre Deutung von außen nicht nachprüfbar ist.","Die Heilerin macht aus der richtigen Idee „Körper und Geist hängen zusammen“ die Begründung, den Knoten nicht abklären zu lassen, obwohl er ernst sein könnte.","Die Bekannte will nur noch „ganzheitlich“ behandelt werden, also nach einem Begriff ohne festen Inhalt, sodass offenbleibt, was bei ihr eigentlich geschieht.","Die Bekannte gibt die Aussage ihrer Heilerin wieder, als sei sie gesichert, und stützt ihr Urteil damit allein auf das Wort der Heilerin statt auf Gründe."],"correctIndex":1,"explanation":"Dass Körper, Psyche und Lebensumstände zusammenhängen, ist unstrittig und gehört zur guten Medizin. Gefährlich wird „ganzheitlich“ erst dort, wo die Zustimmung zu dieser harmlosen Aussage als Freibrief dient, eine konkrete, unbewiesene Methode anzuwenden und dafür eine mögliche ernste Erkrankung nicht untersuchen oder behandeln zu lassen. Entscheidend ist die Folge: Eine nötige, wirksame Abklärung unterbleibt. Ergänzende Verfahren neben der Behandlung sind meist unproblematisch, solange die behandelnde Ärztin davon weiß.","coreRule":"⚡ Die Grenze verläuft dort, wo aus einer wahren Binsenweisheit der Verzicht auf wirksame Behandlung abgeleitet wird.","beleg":"Werkstück D.4.4 (Der Kipppunkt)","status":"entwurf","scenario":"","quote":"","quoteLabel":"","kurz":"Die Idee, dass Körper und Psyche zusammenhängen, ist unstrittig. Zum Problem wird sie, wenn sie dazu dient, einen Knoten nicht abklären zu lassen: Dann unterbleibt genau die Untersuchung, die eine ernste Erkrankung rechtzeitig erkennen könnte.","prueffrage":"Was genau ändert sich für die Bekannte durch den Rat der Heilerin, verglichen mit dem, was sie sonst getan hätte?","rueckmeldung":[{"option":0,"text":"Dass sich eine „Energieblockade“ nicht messen lässt, stimmt und ist ein berechtigter Einwand. Am klarsten wird das Problem dadurch aber nicht, denn entscheidend ist, was daraus folgt: Der Knoten wird nicht abgeklärt, selbst wenn er ernst sein könnte."},{"option":2,"text":"Der Begriff „ganzheitlich“ ist tatsächlich dehnbar. Er allein ist aber noch nicht das Problem: Dass vieles im Körper zusammenhängt, ist unstrittig. Heikel wird es erst, wenn er als Grund dient, eine nötige Untersuchung zu streichen."},{"option":3,"text":"Eine Aussage ungeprüft zu übernehmen, weil sie von einer Heilerin kommt, ist tatsächlich schwach begründet. Das Gewicht liegt hier aber woanders: Selbst eine plausibel klingende Deutung rechtfertigt nicht, einen Knoten nicht untersuchen zu lassen."}],"familie":"ergaenzen-oder-ersetzen","fertigkeit":"F4","quellen":[{"typ":"doi","kurz":"Johnson, S. B.; Park, H. S.; Gross, C. P.; Yu, J. B. (2018): „Use of Alternative Medicine for Cancer and Its Impact on Survival“, JNCI 110(1), 121–124 (Volltext Bezahlschranke, Abstract frei)","oeffentlich":true,"doi":"10.1093/jnci/djx145","abruf":"2026-10-12"},{"typ":"url","kurz":"Segerstrom, S. C.; Miller, G. E. (2004): „Psychological Stress and the Human Immune System“, Psychological Bulletin 130(4), 601–630","oeffentlich":true,"url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC1361287/","abruf":"2026-10-12"}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v8","modell":"claude-sonnet-5-5","datum":"2026-10-15","urteil":"korrigieren","pruefsumme":"039e239d5b45f91c"}},{"id":"qx-d2-044","clusterId":"D","werkstueckRef":"D.4.5","stufe":1,"question":"Ein Coach sagt: „Das Gesetz der Anziehung ist so unumstößlich wie die Schwerkraft. Wenn dein Wunsch nicht eintrifft, hast du es falsch angewendet.“ Du sollst herausfinden, ob das wirklich ein Gesetz im Sinne der Naturwissenschaft ist. Welche Prüffrage deckt das Problem am besten auf?","options":["Wer verdient an den Büchern und Seminaren des Coaches zum Gesetz?","Welches Ergebnis würde das Gesetz der Anziehung eindeutig widerlegen?","Gibt es Zuhörer, bei denen das Gesetz der Anziehung geklappt hat?","Hat der Coach in früheren Vorträgen schon Falsches behauptet?"],"correctIndex":1,"explanation":"Ein Naturgesetz wie die Schwerkraft beschreibt, was beobachtbar geschieht, und ist falsifizierbar: Würde ein losgelassener Apfel zur Decke schweben, wäre das Gesetz widerlegt. Beim „Gesetz der Anziehung“ ist es umgekehrt: Es ist unfalsifizierbar. Bleibt der Wunsch unerfüllt, liegt die Schuld immer beim Anwender, nie beim „Gesetz“. Die Frage nach dem widerlegenden Ergebnis trifft genau diesen Punkt. Die Frage nach dem Verdienst klingt nach einer Prüfung auf Befangenheit, sagt aber etwas über Interessen und nichts über Gültigkeit. Berichte gelungener Fälle klingen nach Belegen, lassen sich bei einer Regel, die jeden Misserfolg erklärt, aber immer finden. Frühere Irrtümer des Coaches klingen nach mangelnder Glaubwürdigkeit, ändern jedoch nichts daran, dass die Behauptung selbst auf ihre Prüfbarkeit hin untersucht werden muss.","coreRule":"⚡ Ein „Gesetz“, das nie scheitern kann, ist kein Naturgesetz: Frag, welches Ergebnis es widerlegen würde.","beleg":"Werkstück D.4.5 (Die zwei Gesetze; Kontext & Tiefe)","status":"entwurf","scenario":"Ein Coach erklärt in einem Vortrag: „Das Gesetz der Anziehung wirkt immer. Wer Reichtum aussendet, bekommt Reichtum. Wenn es bei dir nicht klappt, waren deine Gedanken nicht klar genug oder du hattest unbewusste Blockaden.“","kurz":"Ein Gesetz wie die Schwerkraft lässt sich widerlegen, etwa durch einen Apfel, der zur Decke schwebt. Beim „Gesetz der Anziehung“ liegt die Schuld bei jedem Misserfolg beim Anwender, also kann nichts es widerlegen. Genau das macht es unprüfbar.","prueffrage":"Wie erklärt der Coach einen Wunsch, der eintrifft, und wie einen, der ausbleibt?","rueckmeldung":[{"option":0,"text":"Wer an einer Behauptung verdient, hat ein Interesse, und das darf Skepsis wecken. Ob die Behauptung gilt, hängt aber nicht davon ab, wer von ihr profitiert, sondern davon, ob sie sich prüfen lässt."},{"option":2,"text":"Berichte von gelungenen Fällen wirken wie Belege. Bei einer Regel, die jeden Misserfolg dem Anwender zuschreibt, finden sich solche Fälle aber immer, und sie sagen nichts darüber, ob die Regel überhaupt prüfbar ist."},{"option":3,"text":"Frühere Irrtümer können das Vertrauen in einen Redner mindern. Die aktuelle Behauptung bleibt davon aber unberührt: Sie muss selbst darauf untersucht werden, ob sich überhaupt etwas finden ließe, das sie widerlegt."}],"familie":"widerlegung-benennen","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"Thornton, S.: „Karl Popper“, Stanford Encyclopedia of Philosophy","oeffentlich":true,"url":"https://plato.stanford.edu/entries/popper/","abruf":"2026-10-12"},{"typ":"url","kurz":"Hansson, S. O. (Rev. 2025): „Science and Pseudo-Science“, Stanford Encyclopedia of Philosophy","oeffentlich":true,"url":"https://plato.stanford.edu/entries/pseudo-science/","abruf":"2026-10-12"}],"thema":"Psychologie","pruefung":{"lauf":"quiz-audit-v4","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"ok","pruefsumme":"bd1121482ce79935"}},{"id":"qx-d2-045","clusterId":"D","werkstueckRef":"D.4.5","stufe":2,"question":"Was ist an dieser Erklärung des Coaches das Problem?","scenario":"Du hast drei Monate lang jeden Morgen positiv gedacht, wie dein Coach es nach dem „Gesetz der Anziehung“ verlangt hat, und bist nicht reicher geworden. Der Coach sagt: „Das Gesetz wirkt so zuverlässig wie die Schwerkraft. Wenn sich nichts getan hat, hast du unbewusst negativ gedacht.“","options":["Der Coach lastet das Ausbleiben des Reichtums dir an; so kann das Gesetz selbst nicht scheitern, obwohl eine prüfbare Behauptung scheitern können muss.","Der Coach vergleicht das Gesetz mit der Schwerkraft und leiht ihm so deren Verlässlichkeit, obwohl ein Vergleich nicht zeigt, dass beide gleich gut belegt sind.","Der Coach übersieht den Zeitraum; drei Monate sind für eine spürbare Veränderung des Vermögens kurz, deshalb sagt dein Ergebnis über das Gesetz noch wenig.","Der Coach geht etwas weit, liegt aber nicht ganz falsch; unbewusste negative Gedanken lassen sich nicht ausschließen, deshalb bleibt seine Erklärung möglich."],"correctIndex":0,"explanation":"Eine Behauptung ist nur dann prüfbar, wenn sie scheitern kann. Hier ist das ausgeschlossen: Tritt der Wunsch ein, gilt das als Beweis. Tritt er nicht ein, war angeblich der Glaube nicht stark genug oder es gab unbewusste Blockaden. Damit liegt die Schuld immer beim Anwender und nie bei der Behauptung, und kein denkbares Ergebnis könnte sie widerlegen. Bei der Schwerkraft ist das anders: Schwebte ein losgelassener Apfel zur Decke, wäre sie widerlegt, egal ob jemand daran glaubt. Wer das Scheitern grundsätzlich dem Menschen zuschreibt, schützt seine Behauptung vor jeder Kritik und beschuldigt zugleich die Betroffenen. Außerdem wertet man dann jeden Erfolg als Bestätigung und jeden Misserfolg als eigenes Versagen, was den Bestätigungsfehler verschärft.","coreRule":"⚡ Wenn nur der Anwender scheitern kann, nie die Behauptung, ist es keine Prüfung.","beleg":"Werkstück D.4.5 (Kontext & Tiefe; Der Kipppunkt; Verbindungen)","status":"entwurf","kurz":"Der Coach hat die Behauptung so gebaut, dass kein Ergebnis sie widerlegen kann: Klappt es, bestätigt es das Gesetz, klappt es nicht, warst du schuld. Eine Behauptung, die nicht scheitern kann, ist nicht prüfbar, egal wie sicher sie klingt.","prueffrage":"Wie hätte der Coach es gedeutet, wenn du nach drei Monaten reicher geworden wärst?","rueckmeldung":[{"option":1,"text":"Der Vergleich mit der Schwerkraft verleiht der Behauptung tatsächlich unverdiente Autorität, und ähnlich klingen heißt nicht gleich belegt sein. Der Kern liegt aber woanders: Bei der Schwerkraft wäre ein Gegenbeispiel möglich, beim Coach gilt jedes Ergebnis als Bestätigung."},{"option":2,"text":"Drei Monate sind für eine spürbare Vermögensänderung tatsächlich knapp bemessen. Der Coach beruft sich darauf aber gar nicht: Er erklärt jedes Ausbleiben mit deinen unbewussten Gedanken, und das würde auch nach drei Jahren gelten. An der Dauer liegt das Problem also nicht."},{"option":3,"text":"Unbewusste negative Gedanken lassen sich tatsächlich nicht ausschließen. Genau deshalb trägt die Erklärung nicht: Was sich nie widerlegen lässt, erklärt nichts, und dass etwas möglich bleibt, belegt es noch lange nicht."}],"familie":"immunisierung-erkennen","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Hansson, S. O. (Rev. 2025): „Science and Pseudo-Science“, Stanford Encyclopedia of Philosophy","oeffentlich":true,"url":"https://plato.stanford.edu/entries/pseudo-science/","abruf":"2026-10-12"},{"typ":"url","kurz":"Thornton, S.: „Karl Popper“, Stanford Encyclopedia of Philosophy","oeffentlich":true,"url":"https://plato.stanford.edu/entries/popper/","abruf":"2026-10-12"}],"thema":"Psychologie","pruefung":{"lauf":"quiz-audit-v8","modell":"claude-sonnet-5-5","datum":"2026-10-15","urteil":"korrigieren","pruefsumme":"0bc974c1cdc1c601"}},{"id":"qx-d2-046","clusterId":"D","werkstueckRef":"D.4.5","stufe":3,"question":"Welcher Umgang mit einem solchen Gesetz entspricht dem Prinzip der Falsifizierbarkeit am besten?","options":["Die Wissenschaft sammelt weitere Messungen bei alltäglichen Geschwindigkeiten, wo Newtons Mechanik stimmt, denn viele Bestätigungen wiegen die Abweichungen bei hohen Geschwindigkeiten auf.","Die Wissenschaft ersetzt Newtons Mechanik durch eine genauere Theorie, die sie bei kleinen Geschwindigkeiten als Näherung enthält und die Abweichungen bei hohen Geschwindigkeiten miterklärt.","Die Wissenschaft ergänzt Newtons Mechanik um Zusatzannahmen, die nichts anderes leisten, als die Abweichungen bei hohen Geschwindigkeiten zu erklären, und behält sie ansonsten bei.","Die Wissenschaft lässt die Fachwelt abstimmen und gibt Newtons Mechanik erst auf, wenn die Mehrheit der Physiker sich gegen sie ausspricht, weil Abweichungen sie noch nicht widerlegen."],"correctIndex":1,"explanation":"Ein wissenschaftliches Gesetz ist falsifizierbar: Eine Beobachtung, die ihm widerspricht, zählt als Gegenbeleg. Stößt es nachweislich an Grenzen, ist der beste Ausgang eine genauere Theorie, die alles erklärt, was das alte Gesetz erklärt hat, und dazu die Abweichungen – so löste die Relativitätstheorie Newtons Mechanik ab, die im Alltag als sehr gute Näherung weiter dient. Der Gesprächspartner übersieht diese Möglichkeit zwischen „ausnahmslos wahr“ und „wegwerfen“. Weitere Bestätigungen bei Alltagsgeschwindigkeiten klingen nach Absicherung, heben eine nachgewiesene Abweichung aber nicht auf. Zusatzannahmen klingen nach Verbesserung, machen das Gesetz aber unwiderlegbar, wenn sie nur die Abweichungen wegerklären. Eine Abstimmung klingt demokratisch, doch über die Geltung entscheidet die Beobachtung, nicht die Mehrheit der Fachleute.","coreRule":"⚡ Ein echtes Gesetz darf scheitern und wird dann durch eine genauere Theorie ersetzt. Wer Misserfolge stets dem Anwender oder neuen Ausnahmen zuschreibt, schützt einen Glaubenssatz.","beleg":"Werkstück D.4.5 (Kontext & Tiefe, „Ein wissenschaftliches Gesetz“; Verweis A.20)","status":"entwurf","scenario":"Ein Gesprächspartner sagt: „Ein Gesetz, das irgendwo nachweislich danebenliegt, ist wertlos. Entweder es stimmt ausnahmslos, oder man kann es wegwerfen.“ Du sollst beurteilen, wie die Wissenschaft mit einem Gesetz umgeht, das nachweislich an Grenzen stößt – etwa Newtons Mechanik bei sehr hohen Geschwindigkeiten.","kurz":"Eine nachgewiesene Abweichung ist ein Gegenbeleg, ohne dass das Gesetz damit wertlos wird. Die Falle liegt im Entweder-oder: Es gibt den Mittelweg einer genaueren Theorie, die das Alte als Näherung enthält und die Abweichungen miterklärt.","prueffrage":"Gilt Newtons Mechanik im Alltag weiterhin zuverlässig, und wo genau beginnen die Abweichungen?","rueckmeldung":[{"option":0,"text":"Im Alltagsbereich stimmt Newtons Mechanik tatsächlich sehr gut, das spricht für ihre Brauchbarkeit. Eine nachgewiesene Abweichung bei hohen Geschwindigkeiten gleichen weitere Treffer dort aber nicht aus: Sie bleibt ein Gegenbeleg."},{"option":2,"text":"Zusatzannahmen können sinnvoll sein, wenn sie mehr erklären als nur die Abweichung. Hier leisten sie nichts anderes, als diese wegzuerklären, und genau dadurch würde das Gesetz unwiderlegbar, also nicht mehr prüfbar."},{"option":3,"text":"Eine Abstimmung wirkt fair und gemeinsam getragen. Über die Geltung eines Gesetzes entscheidet aber die Beobachtung, nicht die Mehrheit; eine nachgewiesene Abweichung verschwindet nicht, weil viele Fachleute am Gesetz festhalten."}],"familie":"immunisierung-erkennen","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Thornton, S.: „Karl Popper“, Stanford Encyclopedia of Philosophy","oeffentlich":true,"url":"https://plato.stanford.edu/entries/popper/","abruf":"2026-10-12"},{"typ":"url","kurz":"Hansson, S. O. (Rev. 2025): „Science and Pseudo-Science“, Stanford Encyclopedia of Philosophy","oeffentlich":true,"url":"https://plato.stanford.edu/entries/pseudo-science/","abruf":"2026-10-12"}],"thema":"Geschichte und Wissenschaft","pruefung":{"lauf":"quiz-audit-v4","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"995e32a7228a6ce0"}},{"id":"qx-d2-047","clusterId":"D","werkstueckRef":"D.4.5","stufe":4,"question":"Der Heilpraktiker sagt: „Meine Methode folgt fünf biologischen Naturgesetzen. Wenn eine Behandlung nicht anschlägt, haben Patienten das Gesetz nicht richtig befolgt.“ Was ist an dieser Rechtfertigung am problematischsten?","options":["Er nennt seine Methode „Naturgesetze“; problematisch ist vor allem, dass er ihr so die Autorität echter Gesetze leiht, obwohl sie weder prüfbar noch widerlegbar ist.","Er gibt Patienten die Schuld, wenn die Behandlung nicht anschlägt; problematisch ist vor allem, dass er Kranke damit kränkt und sie zusätzlich zu ihrem Leiden noch belastet.","Er hat seine Methode nicht in Studien geprüft; problematisch ist vor allem diese Lücke, die er mit einer ersten sorgfältig angelegten Studie leicht schließen könnte.","Er antwortet auf die Frage nach Belegen mit einem Verweis auf Gesetze; problematisch ist vor allem, dass er damit ausweicht, statt konkrete Ergebnisse zu nennen."],"correctIndex":0,"explanation":"Ein echtes Naturgesetz beschreibt, was geschieht, macht überprüfbare Vorhersagen und wäre durch ein gegenteiliges Ergebnis widerlegt. Die Methode des Heilpraktikers erfüllt nichts davon: Er nennt keine Prüfung, und jedes Scheitern wird dem Patienten angelastet, sodass nichts sie je widerlegen könnte. Das Wort „Naturgesetz“ erzeugt hier nur den Anschein von Notwendigkeit und Wissenschaftlichkeit. Ein Anspruch dieser Art muss sich an denselben Maßstäben messen lassen wie ein echtes Gesetz: Was sagt er voraus, und was würde ihn widerlegen?","coreRule":"⚡ Wer „Naturgesetz“ sagt, muss Vorhersage und Widerlegbarkeit liefern.","beleg":"Werkstück D.4.5 (Anwendung & Relevanz, „In der Pseudomedizin“; Kernidee)","status":"entwurf","scenario":"Ein Heilpraktiker wirbt für ein Therapiekonzept, das er nie in Studien geprüft hat. Auf Nachfrage verweist er auf „fünf biologische Naturgesetze“. Ein Patient, dem die Behandlung nicht geholfen hat, soll laut ihm selbst schuld sein.","kurz":"Ein Naturgesetz macht prüfbare Vorhersagen und wäre durch ein Gegenbeispiel widerlegt. Wer jedes Scheitern dem Patienten anlastet, kann nie widerlegt werden; „Naturgesetz“ ist dann bloß ein Etikett, das Notwendigkeit und Wissenschaftlichkeit vortäuscht.","prueffrage":"Welche Prüfung seiner Methode nennt der Heilpraktiker, und wie erklärt er den Fall eines Patienten, dem sie nicht geholfen hat?","rueckmeldung":[{"option":1,"text":"Schuld bei Patienten zu suchen, ist unfair und belastend. Wichtiger ist aber, wozu es dient: Jedes Scheitern wird so umgedeutet, und deshalb kann nichts die Methode je widerlegen."},{"option":2,"text":"Dass jede Prüfung fehlt, stimmt, und gerade das macht die Lücke leicht überschätzbar. Eine Studie hilft wenig, wenn jedes Scheitern dem Patienten angelastet wird: Dann gibt es keine Vorhersage, an der sie sich messen ließe."},{"option":3,"text":"Auf die Frage nach Belegen mit Gesetzen zu antworten, ist tatsächlich ein Ausweichen. Doch selbst genannte Einzelergebnisse brächten nichts, solange jedes Scheitern umgedeutet wird. Das Problem steckt im Anspruch selbst, nicht nur im Gespräch."}],"familie":"widerlegung-benennen","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"Thornton, S.: „Karl Popper“, Stanford Encyclopedia of Philosophy","oeffentlich":true,"url":"https://plato.stanford.edu/entries/popper/","abruf":"2026-10-12"},{"typ":"url","kurz":"Hansson, S. O. (Rev. 2025): „Science and Pseudo-Science“, Stanford Encyclopedia of Philosophy","oeffentlich":true,"url":"https://plato.stanford.edu/entries/pseudo-science/","abruf":"2026-10-12"}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v8","modell":"claude-sonnet-5-5","datum":"2026-10-15","urteil":"korrigieren","pruefsumme":"39fd106e212ea6e2"}}]`);export{t as n,n as t};